(window.GIM_TS=window.GIM_TS||{})["Sotah.2"]={"from":48,"a":[["\u0003מעוברת חבירו ומינקת חבירו —\u0004 \u0003לא שותות ולא נוטלות כתובה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003שהיה ר' מאיר אומר: לא ישא אדם מעוברת חבירו ומינקת חבירו\u0004 לפני שמלאו עשרים וארבעה חודשים ללידת הולד, כשייגמל הילד מיניקתו, \u0003ואם נשא —\u0004 \u0003יוציא\u0004 (יגרש) \u0003ולא יחזיר\u0004 אותה \u0003עולמית,\u0004 שקנסוהו על שעבר על דברי חכמים. \u0003וחכמים אומרים: יוציא\u0004 בגט, \u0003וכשיגיע זמנו לכנוס\u0004 (לשאת) לאחר עשרים וארבעה חודש ללידת הולד — \u0003יכנוס\u0004 אותה פעם שניה.","ועוד אמרו: \u0003והרובא\u0004 (בחור, איש צעיר) \u0003שנשא\u0004 אשה \u0003עקרה וזקינה ואין לו אשה ובנים מעיקרא\u0004 \u0005[מתחילה] —\u0006 \u0003לא שותה ולא נוטלת כתובה,\u0004 שהרי נשא אשה האסורה עליו, שהרי אינו יכול לקיים על ידה מצות פריה ורביה שטרם קיימה. \u0003ר' אלעזר אומר:\u0004 אין בנישואין אלה עצמם איסור, שהרי \u0003יכול הוא לישא\u0004 אשה \u0003אחרת ולפרות ולרבות הימנה.\u0004","ומשום כך הריהי שותה \u0003אבל המקנא לארוסתו\u0004 או \u0003לשומרת יבם שלו, ומשכנסה נסתרה —\u0004 \u0003או שותה או לא נוטלת כתובה. מעוברת ומינקת עצמו\u0004 שקינא לה, שיש לחשוש שמא יזיקו המים המרים לוולד, מכל מקום קינויו קינוי ולכן \u0003או שותה או לא נוטלת כתובתה. הרובא\u0004 (הצעיר) \u0003שנשא עקרה וזקינה, ויש לו אשה ובנים\u0004 ואם כן, אין היא אסורה עליו שהרי קיים כבר מצות פריה ורביה — \u0003או שותה, או לא נוטלת כתובה.\u0004","\u0003אשת ממזר\u0004 שהיתה נשואה \u0003לממזר,\u0004 בנישואין כשרים, או \u0003אשת נתין לנתין,\u0004 או \u0003אשת גר\u0004 או \u0003עבד משוחרר,\u0004 או \u0003איילונית\u0004 שקינא לה בעלה — \u0003או שותה, או לא נוטלת כתובה. קתני מיהא\u0004 \u0005[שנה\u0006 התנא \u0005על כל פנים]\u0006 שם ש\u0003איילונית\u0004 שותה, והרי זו \u0003תיובתיה\u0004 \u0005[קושיה חמורה על]\u0006 \u0003רב נחמן\u0004!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב נחמן: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003ואנא דאמרי כי האי תנא\u0004 \u0005[ואני שאמרתי\u0006 את דברי, \u0005כ\u0006דעת \u0005תנא זה\u0006 אמרתי\u0005].\u0006 \u0003דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: איילונית לא שותה ולא נוטלת כתובה, שנאמר: \"ונקתה ונזרעה זרע\"\u0004 (במדבר ה, כח) — \u0003מי שדרכה להזריע, יצאתה זו שאין דרכה להזריע.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים באותה ברייתא שאיילונית שותה, \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"ונקתה ונזרעה זרע\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 הלא אינה בכלל \"ונזרעה זרע\"! ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[נצרך\u0006 הוא \u0005להם לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ונקתה ונזרעה [זרע]\",\u0004 לומר \u0003שאם היתה עקרה —\u0004 \u0003נפקדת\u0004 בבנים, אלו \u0003דברי ר' עקיבא. אמר לו ר' ישמעאל: אם כן —\u0004 \u0003יסתרו כל העקרות,\u0004 וישתו מי סוטה \u0003ויפקדו,\u0004 שיש להן דרך כזו להיפקד, \u0003וזו,\u0004 אשה עקרה שהיא צנועה וכשירה, \u0003הואיל ולא נסתרה הפסידה\u0004 בנים?!","אלא יש לומר: \u0003אם כן מה תלמוד לומר: \"ונקתה ונזרעה זרע\", שאם היתה יולדת\u0004 עד עכשיו \u0003בצער —\u0004 \u0003יולדת\u0004 מעתה \u0003בריוח\u0004 (ברווחה בלא צער), היתה יולדת \u0003נקבות —\u0004 \u0003יולדת\u0004 עכשיו \u0003זכרים,\u0004 היתה יולדת ילדים \u0003קצרים\u0004 (נמוכים) — \u0003יולדת ארוכים\u0004 (גבוהים), היתה יולדת ילדים \u0003שחורים\u0004 שאינם יפים — \u0003יולדת לבנים,\u0004 יפים.","שנינו במשנה ש\u0003אשת ממזר\u0004 הנשואה \u0003לממזר\u0004 שותה. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, שהרי נישואיהם נישואין כשרים! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אפושי\u0004 \u0005[להרבות]\u0006 \u0003פסולין לא ליפוש\u0004 \u0005[נרבה]\u0006 ואין מעוניינים בקיומם של נישואין כאלה, ולכן לא תשתה ותיאסר על בעלה, ולא תלד מעתה ילדים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","עוד שנינו שם: \u0003אשת גר ועבד משוחרר, ואיילונית\u0004 או שותה או לא נוטלת כתובה. ותוהים לגבי אשת גר ועבד כנעני משוחרר (שגם הוא גר): \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, שהרי אשתו היא לכל דבר?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הלא נאמר בראש פרשת סוטה \u0003\"דבר אל בני ישראל\"\u0004 (במדבר ה, יב), ויש מקום לומר שבא הכתוב למעט: בנים של ישראל דווקא, \u0003ולא גרים,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 הברייתא שאף גרים בכלל. ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור ש\u0006כך הוא \u0005גם כן]\u0006 שהכתוב בא באמת למעט גרים! ומשיבים: \u0003\"ואמרת\"\u0004 (במדבר ה, יב) שנאמר אחר כך — לשון \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 ללמד שכל ישראל, אפילו גרים, שותים.","שנינו במשנה: \u0003אשת כהן שותה\u0004 ומותרת לבעלה. ותוהים: \u0003אשת כהן שותה פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ששותה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 הלא אמר הכתוב בסוטה: \u0003\"והיא לא נתפשה\u0004 (נאנסה)\u0003\"\u0004 (במדבר ה, יג) ולכן היא \u0003אסורה, הא\u0004 \u0005[הרי]\u0006 אם \u0003נתפשה\u0004 — \u0003מותרת\u0004 לבעלה. \u0003וזו\u0004 אשת כהן \u0003הואיל ו\u0004גם אם \u0003נתפשה\u0004 \u0003אסורה\u0004 היא לבעלה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא תשתה\u0004 שהרי אין דינה שווה לשאר נשים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003שהיא שותה.\u0004","שנינו במשנה שאשת כהן שותה \u0003ומותרת לבעלה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הלא נבדקה ונמצאה טהורה! \u0003אמר רב הונא:\u0004 מדובר שם \u0003במתנוונה\u0004 שהולך גופה ומתנוון. ותוהים: \u0003מתנוונה —\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003בדקוה מיא\u0004 \u0005[המים]\u0006 והוכיחו שהיא טמאה, אלא שהזכות תולה לה אבל אסורה לבעלה!","ומשיבים: \u0003במתנוונה דרך אברים\u0004 אחרים. כלומר, מחלות באות עליה, אבל לא באיברים האמורים בתורה. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הא זנויי זנאי\u0004 \u0005[זו\u0006 באמת \u0005זנתה],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003לא בדקוה מיא כי אורחיה\u0004 \u0005[המים כדרכם]\u0006 הוא \u0003משום\u0004 ש\u0003באונס זנאי\u0004 \u0005[זנתה]\u0006 \u0003ולגבי כהן\u0004 בכל אופן היא \u0003אסירא\u0004 \u0005[אסורה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003שאין חוששים לכך.\u0004","שנינו במשנה ש\u0003אשת סריס שותה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הלא נשואה היא לו! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הלא \u0003\"\u0004ויתן איש בך את שכבתו \u0003מבלעדי אישך\"\u0004 (במדבר ה, כ) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 \u0003והאי לאו בר הכי\u0004 \u0005[וזה,\u0006 בעלה \u0005אינו מסוגל לכך]\u0006 \u0003הוא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אומרים כן.","\u0003שנינו במשנה ש\u0004\u0003על ידי\u0004 (לשם) \u0003כל עריות מקנין\u0004 (מקנאים) ותוהים: \u0003פשיטא\u0004 \u0003[פשוט,\u0004 מובן מאליו\u0005]\u0006 שכן הוא!"],["\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 הלא נאמר בפרשת סוטה \u0003\"נטמאה\" \"נטמאה\"\u0004 (במדבר ה, יג-יד) \u0003שני פעמים,\u0004 וללמדנו: איסור \u0003אחד לבעל ו\u0004איסור \u0003אחד לבועל.\u0004 והיינו יכולים לומר כי דינה של סוטה הוא דווקא \u0003היכא דקא מיתסרא בהא זנות\u0004 \u0005[במקום שנאסרת בזנות זו],\u0006 \u0003אבל הא\u0004 \u0005[\u0006ערוה \u0005זו]\u0006 \u0003הואיל ו\u0004היא \u0003אסורה וקיימא\u0004 \u0005[ועומדת]\u0006 לבועל, שהרי הוא אסור בה עוד קודם משום ערוה \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יחול בה דין סוטה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על ידי עריות מקנאים.","אמרנו שמכל אלה שנסתרה עמהם מקנאים את האשה \u0003חוץ מן הקטן.\u0004 וטעמו של דבר: \"ושכב \u0003איש\u0004 אותה\" (במדבר ה, יג) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 — \u0003ולא קטן. ו\u0004שנינו שאינו מקנא לה ממי \u0003שאינו איש.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 באה המשנה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שחוף,\u0004 חולה שאין בו כוח ואינו יכול לבוא על אשה ביאה גמורה. \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: שחוף מקנין על ידו, ופוסל\u0004 אשת כהן שבא עליה באיסור, מלאכול \u0003בתרומה!\u0004","ושאלו על דבריו: \u0003מקנין\u0004 \u0005[מקנאים]\u0006 \u0003על ידו, פשיטא\u0004 \u0005[פשוט, מובן מאליו]\u0006 שכן הוא! והסבירו: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 הלא \u0003\"ושכב איש אתה שכבת זרע\"\u0004 (במדבר ה, יג) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 \u0003והא לאו בר הכי\u0004 \u0005[וזה אינו מסוגל לכך]\u0006 \u0003הוא,\u0004 שהרי אינו יכול לבוא עליה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמואל שאף על ידו מקנאים.","ועוד שאלו על דברי שמואל: \u0003\"ופוסל בתרומה\" פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! והשיבו: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003\"ולא יחלל זרעו\"\u0004 (ויקרא כא, טו) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 זה \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003זרע —\u0004 \u0003ליחלל\u0004 \u0005[\u0006יכול הוא \u0005שיחלל],\u0006 ואילו זה \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003זרע —\u0004 \u0003לא ליחלל\u0004 \u0005[יחלל],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדין תלוי בזרע. ומכל מקום לדעת שמואל מקנאים על ידי שחוף!","\u0003ואלא\u0004 נאמר כי מה ששנינו \"שאינו איש\" בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003גוי\u0004 שאין מקנאים על ידו? ושאלו: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב המנונא: גוי מקנין על ידו ופוסל בתרומה.\u0004","ומבררים: \u0003מקנין על ידו פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]?\u0006 והסבירו: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כיון שנאמר בסוטה \u0003\"נטמאה\" \"נטמאה\" שתי פעמים,\u0004 ללמד: \u0003אחד לבעל ואחד לבועל,\u0004 ודין זה נאמר דווקא \u0003היכא דקמיתסרא בהא זנות\u0004 \u0005[במקום שנאסרת\u0006 לבועל \u0005בזנות זו],\u0006 \u0003אבל הא\u0004 \u0005[זו]\u0006 שנבעלה לגוי \u0003הואיל ואסורה וקיימא\u0004 \u0005[ועומדת]\u0006 לבועל זה, שהרי הוא גוי האסור לבת ישראל, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נקיים בה את הכתוב בסוטה, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת מקנאים על ידו.","ועוד שאלו על דברי רב המנונא: \u0003ופוסל בתרומה פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! והסבירו: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003\"ובת כהן כי תהיה לאיש זר\"\u0004 (ויקרא כב, יב) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 לומר: \u0003דבר\u0004 \u0005[\u0006זה \u0005ש\u0006הוא \u0005בן]\u0006 \u0003הויה,\u0004 (נישואין) \u0005—\u0006 \u0003אין\u0004 \u0005[כן]\u0006 פוסל בתרומה, זה \u0003דלאו בר\u0004 \u0005[שאינו בן]\u0006 \u0003הויה —\u0004 \u0003לא,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 רב המנונא \u0003דפסיל\u0004 \u0005[ש\u0006הוא \u0005פוסל]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן,\u0004 ש","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: מנין לגוי,\u0004 או \u0003עבד שבאו על הכהנת,\u0004 או \u0003על הלוייה,\u0004 או \u0003על בת ישראל שפסלוה\u0004 לכהונה ולאכול בתרומה על ידי ביאה זו, \u0003שנאמר: \"ובת כהן כי תהיה אלמנה וגרושה\u0004 וזרע אין לה ושבה אל בית אביה... מלחם אביה תאכל\u0003\"\u0004 (ויקרא כב, יג), לומר: חוזרת היא לאכול תרומה דווקא אם נבעלה ל\u0003מי שיש לו אלמנות וגירושין בה,\u0004 כלומר, לבן ישראל שיש בו נישואין, ולכן יש בו גם אלמנות וגירושין, \u0003יצאו\u0004 מכלל זה \u0003גוי ועבד שאין לו אלמנות וגירושין בה.\u0004 שהרי אין קידושין תופסים בהם, שנפסלה על ידם בתרומה לעולם. ומכל מקום מדברי רב המנונא למדנו שמקנאים גם על ידי גוי!","\u0003ואלא\u0004 אם כן \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 באה המשנה שאמרה \"אינו איש\"? \u0003אמר רב פפא: למעוטי\u0004 \u0005[למעט]\u0006 \u0003בהמה, שאין זנות בבהמה,\u0004 והנבעלת לבהמה איננה נקראת זונה ואין בה דין סוטה.","ובאותו ענין מביאים: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזקיא לרב אשי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מניין דבר זה שאמרו חכמים]\u0006 \u0003אין זנות בבהמה —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תביא אתנן זונה ומחיר כלב\u0004 בית ה' אלהיך לכל נדר\u0003\"\u0004(דברים כג, יט),","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"אתנן כלב\",\u0004 כגון שנתנה אשה טלה לבעל הכלב כדי להיבעל לכלב, או \u0003מחיר זונה\u0004 טלה שקנה בו את הסכמת הזונה להיבעל לו — \u0003מותרין, שנאמר: \"גם שניהם\"\u0004 (דברים כג, יט) להדגיש: \u0003שנים\u0004 אלה (אתנן זונה ומחיר כלב) דווקא אסורים \u0003ולא ארבעה.\u0004 ומכאן שאין זנות לבהמה (כגון כלב), שהרי אין האתנן נחשב לאתנן זונה.","ושואלים: הואיל ולמדנו שמקנאים גם על ידי שחוף שאין לו זרע \u0003ואלא\u0004 מה שנאמר \u0003\"\u0004ושכב איש אותה \u0003שכבת זרע\"\u0004 (במדבר ה, יג) \u0003למה לי,\u0004 מה בא כתוב זה למעט? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך\u0006 הכתוב \u0005לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"שכבת זרע\" —\u0004 הרי זה בא למעט ולומר \u0003פרט לדבר אחר.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"\u0004פרט ל\u0003דבר אחר\"? אמר רב ששת: פרט לשקינא לה\u0004 בעלה שלא יבוא עליה הבועל ש\u0003לא כדרכה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 ש\u0003לא כדרכה\u0004 הלא ביאה גמורה היא, שכן \u0003\"משכבי אשה\"\u0004 (ויקרא יח, כב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 בלשון רבים, ללמדנו: בין כדרכה בין שלא כדרכה משכב גמור הוא!","\u0003אלא אמר רבא: פרט לשקינא לה\u0004 בביאה \u0003דרך אברים\u0004 אחרים, שאינה קרויה ביאה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 ביאה דרך איברים \u0003פריצותא בעלמא\u0004 \u0005[פריצות סתם]\u0006 \u0003היא, ופריצותא מי אסר רחמנא\u0004 \u0005[ופריצות האם אסרה תורה]\u0006 אשה על בעלה בכך, ופשוט הוא ואין צורך למיעוט מיוחד.","\u0003אלא אמר אביי: פרט לשקינא לה בנשיקה,\u0004 כלומר, לא בביאה גמורה אלא רק במגע איברי המין זה בזה. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003העראה\u0004 באשה, שדינה כביאה \u0003זו הכנסת עטרה\u0004 (חלקו העליון של אבר המין הזכרי), \u0003אבל נשיקה,\u0004 מגע בלבד — \u0003ולא כלום היא, היינו דאתי קרא למעוטי\u0004 \u0005[זהו שבא הכתוב למעט]\u0006 \u0003נשיקה\u0004 שאין דינה כביאה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003העראה זו נשיקה,\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ומדוע אין בה דין סוטה?","ומשיבים: לשיטה זו \u0003לעולם\u0004 נפרש \"פרט לדבר אחר\" — \u0003לשקינא לה\u0004 בביאה \u0003דרך אברים\u0004 אחרים. \u0003ו\u0004כך נסביר את החידוש שבדבר: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003בקפידא דבעל תליא רחמנא\u0004 \u0005[בהקפדת הבעל תלתה התורה]\u0006 \u0003ובעל הא קא קפיד\u0004 \u0005[הרי\u0006 הוא \u0005מקפיד]\u0006 גם על מגע כזה, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר תלוי רק בהקפדת בעל, אלא צריך שתהא זו ביאה גמורה.","\u0003אמר שמואל: ישא אדם\u0004"],["\u0003דומה,\u0004 כלומר, מוטב לו לשאת אשה שהכל מדברים בה, שהיא חשודה בזנות, \u0003ואל ישא בת דומה\u0004 בתה של אשה כזו. \u0003שזו,\u0004 החשודה עצמה, \u0003באה מטיפה כשרה,\u0004 שהיא על כל פנים נולדה בכשרות, \u0003וזו,\u0004 בתה, \u0003באה מטיפה פסולה,\u0004 שיש בה חשש ממזרות.","\u0003ור' יוחנן אמר\u0004 להיפך: \u0003ישא אדם בת דומה ואל ישא דומה. שזו,\u0004 הבת, \u0003עומדת בחזקת כשרות\u0004 עצמה, \u0003וזו,\u0004 החשודה, \u0003אינה עומדת בחזקת כשרות.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ר' יוחנן ממה ששנינו בברייתא: \u0003נושא אדם דומה! אמר רבא: ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שאפשר לקבל גירסה זו \u0003\"נושא\"\u0004 שמשמעה \u0003לכתחילה,\u0004 שכך ראוי לו לאדם לעשות?! \u0003אלא,\u0004 שאין לשון ברייתא זאת מדוייקת, וחייב אתה לתקן ולגרוס: \u0003\"אם נשא\",\u0004 אם כן \u0003תני נמי\u0004 \u0005[שנה גם כן]\u0006 ותקן: \u0003\"בת דומה\".\u0004 ואין להוכיח מברייתא זו שלשונה אינה מדוייקת.","ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003ישא אדם בת דומה, ואל ישא דומה. דתני\u0004 \u0005[ששנה]\u0006 \u0003רב תחליפא בר מערבא\u0004 \u0005[בן ארץ ישראל]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו: אשה\u0004 ה\u0003מזנה\u0004 על בעלה — בכל זאת \u0003בניה כשרין,\u0004 שאנו מייחסים את \u0003רוב בעילות\u0004 שנבעלה \u0003אחר הבעל,\u0004 ומן הסתם הילדים נולדו מבעילתו של הבעל ולא מבעילת הנואף.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב עמרם:\u0004 אם \u0003היתה\u0004 האשה \u0003פרוצה ביותר\u0004 שכבר אין לתלות את רוב בעילות בבעל, \u0003מהו?\u0004 האם יש לחשוש לכשרות הילדים? ומסבירים: \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת מי שאומר]\u0006 \u0003אין אשה מתעברת אלא\u0004 בזמן \u0003סמוך לווסתה —\u0004 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שהרי \u0003לא ידע\u0004 \u0005[יודע]\u0006 \u0003בה\u0004 הבעל מתי ווסתה ולכן \u0003לא מנטר לה\u0004 \u0005[שומר אותה]\u0006 מלזנות באותו יום, ובודאי אין בניה כשרים.","אלא \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת מי שאומר]\u0006 ש\u0003אין אשה מתעברת אלא סמוך לטבילתה, מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם נסמוך על כך ש\u0003כיון דידע\u0004 \u0005[ש\u0006בעלה \u0005יודע]\u0006 \u0003בה\u0004 מהו זמן טבילתה, \u0003נטורי מנטר לה\u0004 \u0005[שומר אותה]\u0006 באותו יום שלא תתעבר מאחר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003פרוצה\u0004 היא \u0003ביותר לא\u0004 נאמר שבניה כשרים, שאי אפשר לסמוך גם על שמירה זו? שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה: ואלו שבית דין מקנין להם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת סוטה \u0003\"איש\", מה תלמוד לומר\u0004 כפל הלשון \u0003\"איש איש\u0004 כי תשטה אשתו\" \u0005(במדבר ה, יב) —\u0006 \u0003לרבות אשת חרש, ואשת שוטה, ואשת שעמום\u0004 (משוגע), \u0003ושהלך בעלה למדינת הים, ושהיה חבוש בבית האסורין —\u0004 \u0003שבית דין מקנין להן לפוסלן מכתובתן\u0004 אם נסתרו.","\u0003יכול\u0004 שקינוי בית דין מועיל \u0003אף להשקותן —\u0004 \u0003תלמוד לומר: \"והביא האיש את אשתו\"\u0004 (במדבר ה, טו), דווקא הבעל ולא אחר יכול להשקות את האשה. \u0003ר' יוסי אומר:\u0004 מועיל הדבר \u0003אף להשקותה,\u0004 כלומר, \u0003ולכשיצא בעלה מבית האסורין ישקנה.\u0004","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005חלוקים\u0006 הם\u0005]\u0006 ומשיבים, \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיים את הכתוב \u0003\"וקנא\u0004 את אשתו... \u0003והביא\"\u0004 (במדבר ה, יד-טו) שהמקנא לה הוא המביא אותה להשקותה, \u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 לקיים \u0003\"וקנא... והביא\",\u0004 אלא יכול הבעל להשקותה אף שבית הדין הוא המקנא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \"זאת תורת הקנאות \u0003אשר תשטה אשה תחת אישה\u0004\" \u0005(במדבר ה, כט)\u0006, בא כתוב יתר זה \u0003להקיש\u0004 (להשוות) \u0003איש לאשה ואשה לאיש.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה],\u0006 לאיזה ענין באה השוואה זו? \u0003אמר רב ששת: כשם שאם\u0004 היה \u0003הוא\u0004 הבעל \u0003סומא\u0004 (עיוור) \u0003לא היה משקה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונעלם מעיני אישה\" \u0004 \u0005(במדבר ה, יג)\u0006, כלומר, דווקא אם יכול היה לראות ונעלם ממנו, \u0003כך היא, אם היתה סומא\u0004 (עיוורת) \u0003—\u0004 \u0003לא היתה שותה.\u0004 ולשם כך הועילה ההשוואה, שהיא גזירת הכתוב, אף שאין בה צד של סברה. \u0003רב אשי אמר: כשם שחיגרת וגידמת לא היתה שותה, דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"והעמיד הכהן את האשה לפני ה'... ונתן על כפיה\"\u0004 (במדבר ה, יח), שאם אינה יכולה לעמוד או אין לה ידים לקבל את המנחה — אין משקה אותה, \u0003כך\u0004 גם כן \u0003הוא\u0004 הבעל — \u0003אם היה חיגר או גידם לא היה משקה\u0004 את אשתו. \u0003מר בר רב אשי אמר: כשם שאילמת לא היתה שותה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ואמרה האשה אמן אמן\"\u0004 (\u0003במדבר ה, כב) ואם איננה יכולה לומר —\u0004 אי אפשר לקיים בה מצווה זו, \u0003כך הוא,\u0004 הבעל, \u0003אם היה אילם לא היה משקה\u0004 אותה. \u0003כשם שהמים בודקים אותה, כך המים בודקים אותו,\u0004 את הנואף, \u0003שנאמר\u0004 פעמיים: \u0003\"ובאו\u0004 בה המים המאררים\u0003\"\u0004 (\u0003במדבר ה, כד),\u0004 \u0003\"ובאו\u0004 בה המים המאררים\" (במדבר ה, כז). \u0003וכן כשם שאסורה\u0004 האשה \u0003לבעל\u0004 אם נסתרה ונטמאה — \u0003כך אסורה לבועל, שנאמר: \"נטמאה\" \"ונטמאה\"\u0004 (\u0003במדבר ה, יד.\u0004 \u0003במדבר ה, כט), אלו\u0004 \u0003דברי ר' עקיבא. אמר ר' יהושע: כך היה דורש זכריה בן הקצב. רבי אומר: שני פעמים האמורים בפרשה\u0004 \u0003\"\u0004וקינא את אשתו והיא \u0003נטמאה\"\u0004 (\u0003במדבר ה, יד), ופעם נוספת נאמר\u0004 \u0003\"\u0004אשר תשטה אשה תחת אישה \u0003ונטמאה\"\u0004 (\u0003במדבר ה, כט) —\u0004 \u0003אחד לבעל ואחד לבועל.\u0004","","","","","\u0003בו ביום\u0004 שהעמידו את ר' אלעזר בן עזריה כנשיא הסנהדרין \u0003דרש ר' עקיבא\u0004 על הכתוב \u0003\"ו\u0004כל \u0003כלי חרש אשר יפל מהם אל תוכו כל אשר בתוכו יטמא\"\u0004 (ויקרא יא, לג), \u0003אינו אומר \"טמא\" אלא \"יטמא\",\u0004 ולשון זו באה לומר שלא רק שנטמא לעצמו אלא טמא גם \u0003לטמא אחרים. למד על ככר שני,\u0004 ככר שהיה בתוך כלי חרס שקיבל טומאה משרץ מת, שהכלי הוא ראשון לטומאה והככר שני לטומאה, \u0003שמטמא את השלישי,\u0004 כלומר, אוכל הנוגע בו. \u0003אמר ר' יהושע: מי יגלה עפר מעיניך רבן יוחנן בן זכאי\u0004 שתוכל לחיות ולראות, \u0003שהיית אומר: עתיד דור אחר\u0004 לבוא \u0003ולטהר ככר שלישי,\u0004 לפי \u0003שאין לו\u0004 לשלישי לטומאה \u0003מקרא\u0004 מפורש \u0003מן התורה שהוא טמא, והלא ר' עקיבא תלמידך מביא לו מקרא מן התורה שהוא טמא, שנאמר:\u0004 \u0003\"כל אשר בתוכו יטמא\".\u0004 בו ביום דרש ר' עקיבא, נאמר בערי הלויים: \u0003\"ומדתם מחוץ לעיר את פאת קדמה אלפים באמה...\u0004 זה יהיה להם מגרשי הערים \u0003\"\u0004\u0003(במדבר לה, ה)\u0004 \u0003ומקרא אחר אמר\u0004: \"ומגרשי הערים אשר תתנו ללויים \u0003מקיר העיר וחוצה אלף אמה סביב\u0004\" (במדבר לה, ד).","","","\u0003אי אפשר לומר אלף אמה —\u0004 \u0003שכבר נאמר אלפים אמה, ואי אפשר לומר אלפים אמה —\u0004 \u0003שכבר נאמר אלף אמה, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מיישב אתה את המקראות? — \u0003אלף אמה\u0004 הם \u0003מגרש,\u0004 שטח פנוי סביב העיר, \u0003ואלפים אמה\u0004 נאמר לענין \u0003תחום השבת,\u0004 שאסור לצאת בשבת חוצה לו. ומכאן מצאנו ראיה לאלפיים אמה של תחום שבת מן התורה.","\u0003ר' אליעזר בנו של ר' יוסי הגלילי אומר: אלף אמה\u0004 הם \u0003מגרש, ואלפים אמה\u0004 הם שטח ל\u0003שדות וכרמים.\u0004","\u0003בו ביום דרש ר' עקיבא\u0004 על הכתוב \u0003\"אז ישיר משה ובני ישראל את השירה הזאת לה' ויאמרו לאמר\"\u0004 (שמות טו, א), \u0003שאין תלמוד לומר \"לאמר\",\u0004 שאין למלה \"לאמר\" שום משמעות כאן, \u0003ומה תלמוד לומר \"לאמר\" —\u0004 \u0003מלמד שהיו ישראל עונין שירה אחריו של משה על כל דבר ודבר כקוראין את הלל,\u0004 שהיו חוזרים ועונים על כל פסוק \u0003\"אשירה לה' כי גאה גאה\"\u0004 (שמות טו, א). \u0003לכך נאמר \"לאמר\"\u0004 — שאף הם יאמרו. \u0003ר' נחמיה אומר: כקורין את שמע, ולא כקורין את הלל.\u0004 כלומר, שהיה משה פותח בפסוק וישראל ממשיכים איתו. \u0003בו ביום דרש ר' יהושע בן הורקנוס: לא עבד איוב את הקדוש ברוך הוא אלא מאהבה, שנאמר:\u0004 \u0003\"הן יקטלני לו איחל\"\u0004 (איוב יג, טו). \u0003ועדיין הדבר שקול\u0004 האם הכוונה בכתוב \"לו אייחל\" היא: \u0003לו אני מצפה. או\u0004 שמא הכוונה היא: \u0003איני מצפה?\u0004 שכן יש בכתוב זה קרי (\"לו\") וכתיב (\"לא\"), ואפשר להבין גם: לא אייחל — \u0003תלמוד לומר: \"עד אגוע לא אסיר תמתי ממני\"\u0004 (איוב כז, ה), \u0003מלמד שמאהבה עשה.\u0004 \u0003אמר ר' יהושע: מי יגלה עפר מעיניך רבן יוחנן בן זכאי, שהיית דורש כל ימיך\u0004 ש\u0003לא\u0004 \u0003עבד איוב את המקום אלא מיראה\u0004 בלבד, \u0003שנאמר:\u0004 \u0003\"\u0004ה\u0003איש\u0004 ההוא \u0003תם וישר\u0004 ו\u0003ירא אלהים וסר מרע\"\u0004 (איוב א, א), \u0003והלא יהושע תלמיד תלמידך למד שמאהבה עשה.\u0004","","","","שנינו שכשם שהמים בודקים אותה כך בודקים גם אותו. ושואלים על מה ששנינו \u0003\"אותו\" —\u0004 \u0003למאן\u0004 \u0005[למי]\u0006 את מי הם בודקים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שבודקים \u0003לבעל —\u0004 \u0003בעל מאי עביד\u0004 \u0005[מה\u0006 רע \u0005עשה]\u0006 שהמים בודקים אותו? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006"],["\u0003דאי אית ביה\u0004 \u0005[שאם אין בו]\u0006 \u0003עון\u0004 בדומה לעוונה \u0003בדקי ליה מיא\u0004 \u0005[בודקים אותו המים],\u0006 ואולם האם \u0003כי אית ביה עון בדידיה מי בדקי לה מיא לדידה\u0004 \u0005[\u0006האם \u0005כאשר יש בו עוון האם בודקים המים אותה]\u0006 כלל? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ונקה האיש מעון והאשה ההיא תשא את עונה\"\u0004 (במדבר ה, לא) ללמד: \u0003בזמן שהאיש מנוקה מעון\u0004 — אז \u0003המים בודקין את אשתו,\u0004 אבל אם \u0003אין האיש מנוקה מעון —\u0004 \u0003אין המים בודקין את אשתו!\u0004","\u0003ואלא\u0004 נאמר שהכוונה היא \u0003לבועל\u0004 שהמים פועלים גם עליו, אולם אם כן \u0003ליתני כדקתני סיפא\u0004 \u0005[שישנה\u0006 במפורש \u0005כמו ששנה\u0006 ב\u0005סוף]:\u0006 \u0003כשם שאסורה לבעל כך אסורה לבועל\u0004 ושיאמר אף כאן: כשם שהמים בודקים אותה, כך בודקים הם את הבועל!","ומשיבים: \u0003לעולם\u0004 הכוונה היא \u0003לבועל, ו\u0004לגבי ההבדל בסגנון, \u0003רישא\u0004 \u0005[\u0006ב\u0005ראשה, תחילתה]\u0006 של המשנה — \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003\"\u0004בודקין \u0003אותה\" תני\u0004 \u0005[שנה]\u0006 גם כן \u0003\"\u0004בודקין \u0003אותו\",\u0004 להשוואת הלשון. \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף המשנה] —\u0006 \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \"אסורה ל\u0003בעל\" תנא\u0004 \u0005[שנה]\u0006 גם \"אסורה ל\u0003בועל\".\u0004","שנינו במשנה ראיה לדבר שהמים בודקים גם אותו לדברי ר' עקיבא, \u0003שנאמר:\u0004 \u0003\"ובאו\" \"ובאו\". איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 בגירסת המשנה: האם \u0003\"באו\" \"ובאו\" קאמר\u0004 \u0005[אמר]\u0006 והלימוד הוא מן הוא\"ו היתירה, \u0003או \"ובאו\" \"ובאו\"\u0004 (במדבר ה, כב. במדבר ה, כד. במדבר ה, כז) \u0003קאמר\u0004 \u0005[אמר]\u0006 והלימוד הוא מן הכפילות בפרשה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לשאלה זו מלימוד דומה שבהמשך דברי ר' עקיבא: \u0003כשם שאסורה לבעל כך אסורה לבועל, שנאמר:\u0004 \u0003\"נטמאה\" \"ונטמאה\",\u0004 משמע שהלימוד הוא מריבוי הוא\"ו.","ומקשים: \u0003ועדיין תיבעי\u0004 \u0005[תישאל]\u0006 לך: \u0003\"נטמאה\" \"נטמאה\" קאמר\u0004 \u0005[אמר]\u0006 שם \u0003או \"נטמאה\" \"ונטמאה\" קאמר\u0004 \u0005[אמר],\u0006 שאף כאן יש לשאול שוב האם הלימוד הוא מן הריבוי, או מן הוא\"ו היתירה?","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה\u0006 ב\u0005סוף\u0006 (בהמשך)\u0005],\u0006 \u0003רבי אומר: שני פעמים האמורין בפרשה \"ונטמאה\" \"ונטמאה\" —\u0004 \u0003אחד לבעל ואחד לבועל. מכלל\u0004 זה, ממה שניסח רבי את דבריו כך (\"אחד... ואחד\"), שלמד ממה שנאמר הדבר שתי פעמים, משמע ש\u0003רבי עקיבא ו\"וי קדריש\u0004 \u0005[את הוא\"וים\u0006 הוא \u0005דורש]\u0006 ולא את הכפילות.","\u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003ל\u0004דעת \u0003ר' עקיבא\u0004 בעצם \u0003שיתא קראי כתיבי\u0004 \u0005[ששה כתובים נאמרו]\u0006 בענין זה של \"ובאו המים\", אם מונים את שלוש הפעמים ואת ריבוי הוא\"ו שבהן:","\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 (במדבר ה, כד) — \u0003לצואה דידה\u0004 \u0005[לציווי שלה,\u0006 של האשה\u0005],\u0006 כלומר, שה' אומר ומצווה שכך יהא, \u0003וחד\u0004 \u0005[ואחד],\u0006 הוא\"ו שבו — \u0003לצואה דידיה\u0004 \u0005[לציווי שלו],\u0006 של הבועל, שייבדק גם הוא על ידי המים.","\u0003חד\u0004 \u0005[אחד]\u0006 בתיאור השקאת הסוטה (במדבר ה, כז) — \u0003לעשייה דידה\u0004 \u0005[שלה]\u0006 להודיע שכך ייעשה בה, \u0003וחד\u0004 \u0005[ואחד\u0006 (הוא\"ו)\u0005]\u0006 \u0003לעשייה דידיה\u0004 \u0005[שלו],\u0006 ללמד שכך נעשה גם בו.","\u0003חד\u0004 \u0005[אחד]\u0006 (במדבר ה, כב) — \u0003לידיעה דידה\u0004 \u0005[שלה]\u0006 שמודיע לה הכהן שכך יהיה בה, \u0003וחד\u0004 \u0005[ואחד\u0006 (הוא\"ו)\u0005] —\u0006 \u0003לידיעה דידיה\u0004 \u0005[שלו].\u0006","\u0003ו\u0004לדעת \u0003רבי תלתא קראי כתיבי\u0004 \u0005[שלושה כתובים נאמרו]\u0006 כיון שאינו דורש את הואוי\"ם היתירים: \u0003חד\u0004 \u0005[אחד] —\u0006 \u0003לצואה\u0004 \u0005[לציווי]\u0006 שלה, \u0003וחד\u0004 \u0005[ואחד]\u0006 — \u0003לעשייה\u0004 שלה \u0003וחד\u0004 \u0005[ואחד] —\u0006 \u0003לידיעה\u0004 שלה.","ושואלים: \u0003ורבי,\u0004 ענין זה ש\u0003כשם שהמים בודקים אותה כך בודקין אותו מנא ליה\u0004 \u0005[מניין לו]?\u0006","\u0003ומשיבים:\u0004 \u0003נפקא ליה מדתניא\u0004 \u0005[יוצא לו\u0006 נלמד הדבר \u0005מ\u0006מה \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"לצבות בטן ולנפל ירך\"\u0004 (במדבר ה, כב) אלה הם \u0003בטנו ויריכו של בועל. אתה אומר\u0004 שהכוונה היא \u0003בטנו ויריכו של בועל, או אינו אלא בטנה ויריכה של\u0004 ה\u0003נבעלת? כשהוא אומר \"וצבתה בטנה ונפלה ירכה\"\u0004 (במדבר ה, כז) \u0003הרי בטנה ויריכה של נבעלת אמור\u0004 במפורש, \u0003ומה אני מקיים\u0004 את הכתוב \u0003\"לצבות בטן ולנפל ירך\" —\u0004 \u0003בטנו ויריכו של בועל.\u0004","\u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' עקיבא, שאינו לומד מכאן, סבור כי הכתוב \u0003ההוא\u0004 בא לומר \u0003דמודע\u0004 \u0005[שמודיע]\u0006 \u0003לה\u0004 ה\u0003כהן\u0004 שה\u0003בטן ברישא\u0004 \u0005[בתחילה]\u0006 נפגעת \u0003והדר\u0004 \u0005[ואחר כך]\u0006 ה\u0003ירך,\u0004 ש\u0003לא\u0004 \u0003להוציא לעז על המים המרים.\u0004 שאם לא יודיעוה, תאמר שמה שקרה לא היה מפני המים המרים אלא מטעם אחר, שהרי הכהן אמר לה קודם (במדבר ה, כא) \"ירכך נופלת\" ואחר כך \"ואת בטנך צבה\".","\u0003ואידך\u0004 \u0005[והאחר],\u0006 רבי, סבור: \u0003אם כן, לכתוב קרא\u0004 \u0005[שיכתוב הכתוב]\u0006 \u0003\"בטנה ויריכה\", מאי\u0004 \u0005[מה]\u0006 הלשון הכללית \u0003\"בטן\" ו\"ירך\" —\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהכוונה \u0003לבועל.\u0004","ושואלים: אם כך, \u0003ואימא כולי להכי\u0004 \u0005[ואמור\u0006 שהפסוק \u0005כולו לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 שהמים בודקים את הבועל, ולא בא ללמד כלל על האשה? ומשיבים: \u0003אם כן לכתוב\u0004 \u0003[שיכתוב]\u0004 \u0003\"בטנו ויריכו\", מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"בטן\" ו\"ירך\"\u0004 שהיא לשון כללית — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005].\u0006","שנינו במשנה, \u0003אמר ר' יהושע: כך,\u0004 כר' עקיבא, \u0003היה דורש זכריה\u0004 בן הקצב. רבי אומר: שני פעמים האמורים בפרשה \"ונטמאה\" \"ונטמאה\" — אחד לבעל ואחד לבועל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלש פעמים האמורין\u0004 בפרשה \"והיתה \u0003אם נטמאה\"\u0004 \u0005(במדבר ה, כז)\u0006 \"וקינא את אשתו והיא \u0003נטמאה\"\u0004 \u0005(במדבר ה, יד)\u0006 \"אשר תשטה אשה תחת אישה \u0003ונטמאה\"\u0004 \u0005(במדבר ה, כט)\u0006 \u0003למה?\u0004 — \u0003אחד\u0004 שהיא טמאה ואסורה \u0003לבעל, ואחד לבועל, ואחד לתרומה\u0004 שאסורה לאכול, אם היתה כהנת או נשואה לכהן, אלו \u0003דברי ר' עקיבא.\u0004","\u0003אמר ר' ישמעאל:\u0004 הלא \u0003קל וחומר\u0004 הוא; \u0003ומה גרושה\u0004 (בת כהן) \u0003שמותרת לתרומה —\u0004 \u0003אסורה לכהונה, זו,\u0004 הסוטה, \u0003שאסורה בתרומה —\u0004 \u0003אינו דין שאסורה לכהונה?\u0004","ועוד דרשו בענין זה: \u0003מה תלמוד לומר\u0004 בתיאור המקרים בהם משקה הבעל את אשתו \u0003\"והיא נטמאה\"\u0004 (במדבר ה, יד) ובהמשך אותו פסוק נאמר \u0003\"והיא לא נטמאה\"\u0004 — לומר כך: \u0003אם נטמאה למה שותה, אם לא נטמאה למה משקה? מגיד לך הכתוב שהספק אסורה,\u0004 שנאסרת על בעלה אפילו מחמת הספק, ואינה מותרת לו עד שיתברר הדבר.","\u0003ומכאן אתה דן\u0004 ולמד \u0003ל\u0004דינו של \u0003שרץ\u0004 מת, אם יש ספק טומאה על ידו: \u0003ומה סוטה,\u0004 \u0003שלא עשה בה שוגג כמזיד ו\u0004לא עשה בה \u0003אונס כרצון,\u0004 שאם שגגה או נאנסה אינה נבדקת — בכל זאת \u0003עשה בה ספק כודאי,\u0004 שמפני הספק בלבד היא נאסרת עד שיתברר הדבר, \u0003שרץ\u0004 (או שאר טומאות) \u0003שעשה בו שוגג כמזיד ואונס כרצון,\u0004 שהרי עצם מגעו מטמא, ואין כל הבדל כיצד אירע הדבר — \u0003אינו דין שיעשה בו ספק\u0004"],["\u0003כודאי\u0004 ולכן ספק טומאת שרץ אסורה.","\u0003וממקום שבאת,\u0004 מסוטה, שמשם למדנו דין ספק טומאת השרץ, יש ללמוד אף פרטי דינים בענין ספק טומאה: \u0003מה סוטה\u0004 אין ספק טומאתה הופך לודאי אלא ב\u0003רשות היחיד\u0004 שהרי היא נאסרת משום שנסתרה, ואין אפשרות של סתירה ברשות הרבים — \u0003אף שרץ\u0004 ספיקו מטמא ב\u0003רשות היחיד\u0004 בלבד.","\u0003ומה סוטה\u0004 הריהו \u0003דבר שיש בו דעת לישאל,\u0004 שהרי אפשר לשאול אותה אם נטמאה או לא נטמאה — \u0003אף שרץ,\u0004 אין ספק טומאה בו טמא אלא ב\u0003דבר שיש בו דעת לישאל\u0004 כגון אדם שספק נטמא, או בדבר שספק נטמא והיה שם אדם שיכול היה לדעת.","\u0003ומכאן אמרו: דבר שיש בו דעת לישאל, ברשות היחיד —\u0004 \u0003ספיקו טמא, ברשות הרבים—\u0004 \u0003ספיקו טהור. ו\u0004דבר \u0003שאין בו דעת לישאל, בין ברשות היחיד בין ברשות הרבים —\u0004 \u0003ספיקו טהור.\u0004 עד כאן לשון הברייתא.","ותחילה שואלים לגבי פירוש חילופי הדברים בין החכמים: \u0003ור' ישמעאל\u0004 מה משמעות דבריו? הרי \u0003אמר ר' עקיבא\u0004 שיש בסוטה איסור \u0003תרומה, ומהדר ליה איהו\u0004 \u0005[ומחזיר\u0006 ומשיב \u0005לו הוא]\u0006 לענין דין \u0003כהונה?\u0004 והרי ר' עקיבא לא הזכיר כלל שאסורה לכהונה!","\u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003לר' עקיבא,\u0004 הלכה זו שאסורה ל\u0003כהונה מנא ליה\u0004 \u0005[מניין לו]?\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003כהונה לא צריכא קרא\u0004 \u0005[אינה צריכה כתוב]\u0006 מיוחד כדי ללמד עליה,"],["\u0003שהרי עשה בה\u0004 בסוטה \u0003ספק זונה כזונה\u0004 שהיא נאסרת על בעלה מפני הספק בלבד, וכיון שנעשתה כזונה הרי זונה אסורה לכהן. אולם אם כן \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי קרא\u0004 \u0005[תצטרך כתוב]\u0006 מפורש, \u0003שהרי עשה בה ספק זונה כזונה,\u0004 וזונה אסורה בתרומה!","\u0003אלא\u0004 יש לומר כי \u0003ל\u0004דעת \u0003ר' עקיבא ארבעה קראי כתיבי\u0004 \u0005[כתובים נאמרו]\u0006 שדורש גם את כפל הלשון \"נטמאה\" וגם את הוא\"ו היתירה של המלה \"ונטמאה\": \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 לאוסרה \u0003לבעל, וחד\u0004 \u0005[ואחד]\u0006 לאוסרה \u0003לבועל, וחד\u0004 \u0005[ואחד]\u0006 לאוסרה \u0003לכהונה, וחד\u0004 \u0005[ואחד]\u0006 לאוסרה \u0003לתרומה. ו\u0004לדעת","\u0003ר' ישמעאל\u0004 שאינו דורש את יתור הוא\"ו \u0003תלתא קראי כתיבי\u0004 \u0005[שלושה כתובים נאמרו]:\u0006 \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 \u0003לבעל, וחד\u0004 \u0005[ואחד]\u0006 \u0003לבועל, וחד\u0004 \u0005[ואחד]\u0006 \u0003לתרומה, ו\u0004אילו \u0003כהונה אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 \u0003בקל וחומר\u0004 מתרומה.","ושואלים: \u0003ור' ישמעאל, ממאי דאיצטריך קרא\u0004 \u0005[ממה,\u0006 מניין יודע הוא \u0005שהוצרך הכתוב]\u0006 \u0003לתרומה, וכהונה אתיא\u0004 \u0005[באה]\u0006 \u0003בקל וחומר? דילמא כי אצטריך\u0004 \u0005[שמא כאשר הוצרך]\u0006 הפסוק הרי זה \u0003לכהונה\u0004 בלבד, \u0003ו\u0004אילו \u0003תרומה שריא\u0004 \u0005[מותרת]\u0006 לה!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ר' ישמעאל: \u0003מסתברא דומיא\u0004 \u0005[מסתבר\u0006 ללמוד מן הפסוק איסור ב\u0005דומה]\u0006 לאיסור \u0003בעל ובועל. מה בעל ובועל\u0004 הם איסורים החלים על האשה \u0003מחיים\u0004 (בחיי הבעל) — \u0003אף תרומה נמי\u0004 \u0005[גם כן]\u0006 היא איסור \u0003מחיים, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003כהונה\u0004 שהוא איסור שחל עליה רק \u0003לאחר מיתה\u0004 של הבעל, שאם בחייו יגרשנה תהיה אסורה ממילא לכהן כגרושה.","\u0003ור' עקיבא,\u0004 סברה זו של \u0003דומיא\u0004 \u0005[איסור\u0006 ב\u0005דומה]\u0006 לאיסור \u0003בעל ובועל לית ליה\u0004 \u0005[אין לו],\u0006 אינו סבור שיש ללמוד מהשוואה זו, ולכן צריך שני לימודים; אחד לתרומה ואחד לכהונה.","\u0003ואי נמי אית ליה\u0004 \u0005[ואם גם כן יש לו]\u0006 השוואה זו, סבור הוא ש\u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 שנלמד\u0005]\u0006 \u0003בקל וחומר\u0004 בכל זאת \u0003טרח וכתב לה קרא\u0004 \u0005[טורח וכותב אותו הכתוב\u0006 במפורש\u0005].\u0006 ואף כאן, למרות שאפשר ללמוד איסור כהונה מתרומה בקל וחומר, בכל זאת נכתב הדבר במפורש.","\u0003אמר רב גידל אמר רב: דבר שיש בו דעת לישאל ואין בו דעת לישאל\u0004 לענין ספק טומאה \u0003מהאי קרא נפקא\u0004 \u0005[מפסוק זה\u0006 הוא \u0005יוצא],\u0006 שנאמר: \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 (ויקרא ז, יט) ומכאן נלמד: \u0003ודאי טמא הוא\u0004 ש\u0003לא יאכל, הא\u0004 \u0005[הרי]\u0006 \u0003ספק טמא וספק טהור —\u0004 \u0003יאכל.\u0004","ולעומת זאת \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופו]\u0006 של אותו פסוק: \u0003\"והבשר כל טהור יאכל בשר\"\u0004 (ויקרא ז, יט), משמע: \u0003ודאי טהור הוא\u0004 ש\u0003יאכל בשר, הא\u0004 \u0005[הרי]\u0006 \u0003ספק טמא וספק טהור —\u0004 \u0003לא יאכל.\u0004 אם כן יש סתירה הנובעת מדיוק ומיצוי לשונו של פסוק זה.","\u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תלמד מכך]:\u0006 \u0003כאן —\u0004 \u0003שיש בו דעת לישאל,\u0004 שהאיש עצמו נגע (\"כל טהור\") ולכן ספיקו טמא, \u0003כאן\u0004 כשהבשר הטמא נגע (\"והבשר\") הרי זה דבר \u0003שאין בו דעת לישאל\u0004 וספיקו טהור.","ומעירים: \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 לענין זה מה שלמד \u0003רב גידל אמר רב, ואיצטריך למיגמר\u0004 \u0005[והוצרך\u0006 גם \u0005להילמד]\u0006 \u0003מסוטה. דאי\u0004 \u0005[שאם]\u0006 רק \u0003מ\u0004דברי \u0003רב הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי ספק טומאה בדבר שיש בו דעת להישאל, טמא \u0003בין ברשות היחיד ובין ברשות הרבים,\u0004 לכן \u0003איצטריך למיגמר\u0004 \u0005[צריך היה ללמוד]\u0006 \u0003מסוטה\u0004 שרק ברשות היחיד כך הוא.","וכן גם להיפך: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מסוטה\u0004 בלבד היו למדים, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שכשם שבסוטה גם הסוטה וגם הצד האחר לטומאה, הבועל, יש להם דעת ויכולים להישאל, כך גם בכל ספק מגע טומאה — לא יהיה הספק טמא \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003דעת נוגע ו\u0004דעת \u0003מגיע,\u0004 כלומר, המטמא והנטמא, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 גם לדברי רב גידל אמר רב, שדי באחד מהם שיש בו דעת להישאל, כדי לטמא ספק טומאה ברשות היחיד.","שנינו במשנה: \u0003בו ביום דרש ר' עקיבא וכל כלי חרש כו'.\u0004 שככר טמא, שהוא שני לטומאה, מטמא ככר תרומה אחר שנגע בו, וסיפר ר' יהושע שסבור היה רבן יוחנן בן זכאי שיקום דור ויטהרנו, מאחר שאין לו מקרא כתוב.","ושואלים: ו\u0003מאחר שאין לו\u0004 מקרא, \u0003למה\u0004 החזיק רבן יוחנן בהנחה שהוא \u0003טמא?\u0004","\u0003אמר רב יהודה אמר רב:\u0004 סבור היה ש\u0003מן ה\u0004כתוב במפורש ב\u0003תורה אין לו\u0004 טומאה, אבל \u0003מדין קל וחומר יש לו.\u0004 ומהו קל וחומר זה: \u0003ומה טבול יום\u0004 (אדם שטבל מטומאתו ועדיין לא נטהר לגמרי עד סוף אותו יום) \u0003שמותר בחולין\u0004 ואינו פוסלם, ונקרא טהור לענין חולין (רמב\"ן) — \u0003פוסל בתרומה\u0004 אם נגע בה, כפי שאנו למדים מן הכתובים, \u0003ככר שני שפסול בחולין\u0004 שקיבל טומאה מראשון לטומאה, ומכל מקום קרוי טמא — \u0003אינו דין שיעשה שלישי בתרומה?\u0004","ומעירים: קל וחומר זה \u0003איכא למיפרך\u0004 \u0005[יש\u0006 אפשרות \u0005לפרוך,\u0006 לשבור אותו\u0005]\u0006 בטענה הבאה: \u0003מה לטבול יום שכן\u0004 היה \u0003אב הטומאה\u0004 לפני שטבל, מה שאין כן ככר זה שהוא רק שני לטומאה מתחילתו!","ומשיבים: \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו"],["\u0003מטבול יום\u0004 של \u0003שרץ\u0004 אדם שנטמא בשרץ וטבל, ומתחילה לא היה האיש אלא ראשון לטומאה, ובכל זאת פוסל הוא את התרומה!","ומקשים: והרי עדיין יש לפרוך את הקל וחומר, \u0003מה לטבול יום\u0004 של \u0003שרץ —\u0004 \u0003שכן\u0004 יכול להיות \u0003במינו,\u0004 בטבול יום, גם \u0003אב הטומאה\u0004 מה שאין כן באוכלים, שלעולם אינם נעשים אב הטומאה!","ומשיבים: \u0003כלי חרש יוכיח\u0004 שאין במינו אב הטומאה ובכל זאת מטמא את התרומה.","ומקשים: הלא אפשר לדחות: \u0003מה לכלי חרש\u0004 שיש בו צד טומאה חמור אחר — \u0003שכן מטמא מאוירו,\u0004 שדבר הנכנס בחללו של כלי חרס טמא — נטמא, ואינו צריך לשם כך מגע ישיר עם המטמא!","ומשיבים: \u0003טבול יום יוכיח\u0004 שיש בו חומרה זו שפוסל תרומה אף שאינו מטמא באויר אלא רק במגע ישיר,","\u0003ו\u0004אם כן \u0003חוזר הדין\u0004 מצד זה לצד זה. שאם רצונך לתת טעם מסויים לחומרה זו יש ראיה מן הדין השני שאין בו צד זה, וכן להיפך; \u0003לא ראי זה כראי זה\u0004 (לא זה דומה לזה) \u0003ולא ראי זה כראי זה, הצד השוה שבהן —\u0004 \u0003שמותרין בחולין, ופוסלין בתרומה,\u0004 ומכאן נלמד בקל וחומר: \u0003כל שכן ככר שני שפוסל בחולין\u0004 — ש\u0003פוסל בתרומה. ו\u0004אותו","\u0003דור אחר\u0004 שסבר רבן יוחנן בן זכאי שיטהרנו, \u0003פריך\u0004 \u0005[מקשה]\u0006 על כך: \u0003מה להצד השוה שבהן\u0004 בטבול יום ובכלי חרס — \u0003שכן יש בהן צד חמור,\u0004 שכל אחת מן החומרות הללו אינה מצויה בכל הטומאות.","\u0003ו\u0004אילו \u0003רבן יוחנן בן זכאי\u0004 עצמו, \u0003צד חמור לא פריך\u0004 \u0005[מקשה],\u0006 שלדעתו קיומו של צד חמור שאינו משותף לשני המקרים אינו נימוק לפרוך קל וחומר.","אגב כך מביאים אתה ש \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: מנין לרביעי בקודש שפסול\u0004 על ידי מגע של שלישי לטומאה?","ומפרש: \u0003ודין\u0004 (קל וחומר) \u0003הוא.\u0004 שכך אפשר לומר: \u0003מה מחוסר כיפורים\u0004 (כגון יולדת או זב), שכבר נטהר מטומאתו החמורה על ידי טבילה והערב שמש אך צריך להביא קרבן, ועד שלא יביא קרבן לכפרתו אף ש\u0003מותר\u0004 הוא \u0003בתרומה\u0004 — מכל מקום \u0003פסול בקודש.\u0004 דבר שהוא \u0003שלישי\u0004 לטומאה, \u0003שפסול\u0004 \u0003בתרומה —\u0004 \u0003אינו דין הוא שיעשה רביעי\u0004 לטומאה \u0003בקודש?\u0004","\u0003ולמדנו\u0004 איפוא \u0003שלישי לקודש מן התורה, ורביעי מקל וחומר.\u0004","ומפרשים: \u0003שלישי לקודש מן התורה מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 (ויקרא ז, יט). \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אף במקרה ש\u0003נגע בשני\u0004 לטומאה (\"כל טמא\" — כל שיש בו טומאה) \u0003ואמר רחמנא\u0004 \u0005[ואמרה תורה]\u0006 \u0003\"לא יאכל\". רביעי מקל וחומר —\u0004 \u0003כדאמרן\u0004 \u0005[כפי שאמרנו].\u0006","\u0003אמר ר' יוחנן:\u0004 ה\u0003טעם\u0004 של \u0003בריבי\u0004 (אדם גדול זה), ר' יוסי, \u0003איני יודע מה הוא, שהרי\u0004 קל וחומר זה, \u0003תשובתו\u0004 (דחייתו) \u0003בצדו: אוכל הבא,\u0004 כלומר, הנטמא \u0003מחמת\u0004 מגע \u0003טבול יום יוכיח, שפסול בתרומה —\u0004 \u0003ואינו עושה רביעי בקודש.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אבא שאול אומר: טבול יום תחילה לקודש\u0004 כלומר, נחשב כראשון לטומאה לענין קדשים \u0003לטמא שנים\u0004 (שתי דרגות): את מה שהוא נוגע בו, ואת הדבר שנוגע באותו דבר, \u0003ולפסול אחד\u0004 שהשלישי שנגע בו שהוא רביעי בקודש אינו מטמא אחרים אבל פסול בעצמו מטעם טומאה.","\u0003ר' מאיר אומר:\u0004 טבול יום נחשב כשני לטומאה: \u0003מטמא אחד\u0004 את מה שהוא נוגע בו, \u0003ופוסל\u0004 רק \u0003אחד\u0004 אחריו. \u0003וחכמים אומרים: כשם ש\u0004טבול יום \u0003פוסל אוכלי תרומה ומשקי תרומה —\u0004 \u0003כך פוסל אוכלי קודש ומשקי קודש,\u0004 אבל אינו מטמא אותם לטמא אחרים. ואם כן רואים אנו כי לדעת חכמים טבול יום הפוסל תרומה רק פוסל קדשים, אבל אינו מטמא לטמא אחרים, כלומר, לעשות רביעי בקודש!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 יודע אתה ש\u0003ר' יוסי כרבנן סבירא ליה\u0004 \u0005[כ\u0006שיטת \u0005חכמים סבור הוא]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כ\u0004שיטת \u0003אבא שאול סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר\u0004 שטבול יום יכול במגעו \u0003לטמא שנים ולפסול אחד!\u0004","ודוחים: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שר' יוסי \u0003כאבא שאול סבירא ליה\u0004 \u0005[סבור הוא]\u0006 אם כן \u0003לייתיה\u0004 \u0005[שיביא,\u0006 ילמד \u0005אותו]\u0006 \u0003לרביעי בקודש\u0004 בראיה טובה יותר, \u0003מאוכל שבא\u0004 (שנטמא) \u0003מחמת\u0004 מגע \u0003טבול יום.\u0004","וכך יאמר: \u0003ומה אוכל הבא מחמת טבול יום,\u0004 ש\u0003טבול יום גופיה\u0004 \u0005[עצמו]\u0006 \u0003מותר בחולין —\u0004 \u0003אמרת\u0004 שהוא \u0003עושה רביעי בקודש, אוכל\u0004"],["\u0003שלישי הבא מחמת שני,\u0004 ש\u0003שני גופיה\u0004 \u0005[עצמו]\u0006 \u0003אסור בחולין —\u0004 \u0003אינו דין שעושה רביעי בקודש?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שלא השתמש בקל וחומר זה \u0003משום דאיכא למיפרך\u0004 \u0005[שאפשר להקשות]:\u0006 \u0003מה לטבול יום שכן\u0004 היה מתחילה \u0003אב הטומאה\u0004 — \u0003הא אייתינה\u0004 \u0005[הרי\u0006 ר' יוסי \u0005הביא אותה]\u0006 השתמש בלימוד כזה \u0003ממחוסר כיפורים, ולא פרכיה\u0004 \u0005[פרך אותו]\u0006 מטעם זה, אף שמחוסר כיפורים גם הוא היה קודם לכן אב הטומאה, משמע שאיננו חושש לפירכה זו!","\u0003אמר רב אסי אמר רב, ואמרי לה\u0004 \u0005[\u0006ויש \u0005אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רבה בן איסי אמר רב: ר' מאיר, ור' יוסי, ור' יהושע, ור' אלעזר, ור' אליעזר —\u0004 \u0003כולהו סבירא להו\u0004 \u0005[כולם סבורים הם],\u0006 ש\u0003אין שני עושה שלישי בחולין\u0004 והוא מוכיח את הדברים:","\u0003ר' מאיר —\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הטעון ביאת מים\u0004 (טבילה) \u0003מדברי סופרים,\u0004 שחכמים נתנו לו דין כשני לטומאה, \u0003מטמא את הקודש, ופוסל את התרומה, ומותר בחולין ובמעשר,\u0004 אלו \u0003דברי ר' מאיר,\u0004 ומכיון שלדעתו מותר בחולין ודאי שאינו עושה שלישי בחולין. \u0003וחכמים אוסרין במעשר.\u0004","\u0003ר' יוסי —\u0004 \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 ש\u0003אם איתיה\u0004 \u0005[יש]\u0006 צד לומר שהוא סבור ששני עושה שלישי בחולין, אם כן \u0003לייתיה\u0004 \u0005[שיביא,\u0006 שילמד \u0005אותו]\u0006 \u0003לרביעי בתרומה\u0004 מקל וחומר: ומה טבול יום שמותר בחולין פוסל בתרומה, ככר שלישי שפסול בחולין אינו דין שיעשה רביעי בתרומה. \u0003ו\u0004מתוך כך ל\u0003חמישי בקודש\u0004 מקל וחומר: ומה מחוסר כיפורים שמותר בתרומה פסול בקודש, רביעי שפסול בתרומה אינו דין שיעשה חמישי בקודש.","\u0003ר' יהושע —\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' אליעזר אומר:\u0004 אדם \u0003האוכל אוכל ראשון\u0004 לטומאה נעשה \u0003ראשון\u0004 לטומאה, האוכל אוכל \u0003שני\u0004 — נעשה \u0003שני, שלישי\u0004 — נעשה \u0003שלישי.\u0004 \u0003ר' יהושע אומר: האוכל אוכל ראשון ואוכל שני\u0004 — נעשה \u0003שני,\u0004 האוכל אוכל \u0003שלישי\u0004 — נעשה \u0003שני בקודש\u0004 שאף מאכל קודש שיגע בו יפסול את הקודש במגעו, \u0003ואין\u0004 הוא נעשה \u0003שני בתרומה\u0004 — לפוסלה.","וכל זה מדובר \u0003ב\u0004אדם שאכל \u0003חולין שנעשו על טהרת תרומה\u0004 שהיו נזהרים בטהרת חולין אלה כאילו היו תרומה.","ונדייק: \u0003על טהרת התרומה —\u0004 \u0003אין\u0004 \u0005[כן],\u0006 אבל חולין שנעשו \u0003על טהרת הקודש\u0004 שנזהרו בטהרתם כאילו היו קדשים — \u0003לא,\u0004 ודינם כחולין רגילים.","\u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]:\u0006 \u0003אין שני עושה שלישי בחולין.\u0004","\u0003ר' אלעזר —\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: שלשתן שוין, הראשון שבקודש ו\u0004הראשון \u0003שבחולין ו\u0004הראשון \u0003שבתרומה\u0004 — כל אחד מהם","\u0003מטמא שנים\u0004 (שתי דרגות זו אחר זו, שני ושלישי) \u0003ופוסל אחד\u0004 אחריהם, דהיינו רביעי \u0003בקודש,\u0004","\u0003מטמא אחד\u0004 (שני בתרומה) \u0003ופוסל אחד\u0004","\u0003דהיינו שלישי\u0004 \u0003בתרומה, ופוסל אחד\u0004 בלבד \u0003בחולין,\u0004 כלומר, שני מכאן שלדעתו אין שלישי לטומאה בחולין.","\u0003ר' אליעזר\u0004 סבור כן, כמו \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: חלה ניטלת מן\u0004 העיסה \u0003הטהורה על\u0004 העיסה \u0003הטמאה, כיצד?\u0004 היו \u0003שתי עיסות אחת טהורה ואחת טמאה —\u0004 \u0003נוטל כדי\u0004 שיעור \u0003חלה\u0004 עבור שתי העיסות \u0003מעיסה\u0004 טהורה ש\u0003לא\u0004 \u0003הורמה חלתה, ונותן פחות מכביצה\u0004 ממנה, כלומר, שיעור של אוכל שאינו מטמא, \u0003באמצע\u0004 בין הטמאה והטהורה \u0003כדי ליטול\u0004 את החלה \u0003מן המוקף\u0004 (הסמוך), כלומר, מן העיסה הטמאה הסמוכה לה."],["\u0003וחכמים אוסרין\u0004 לעשות כן.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 שלדעת ר' אליעזר יכול לתת באמצע אף עיסה ששיעורה \u0003כביצה,\u0004 המטמאת אוכלים אחרים.","\u0003סברוה\u0004 \u0005[חשבו]\u0006 אותם חכמים שרצו להוכיח מכאן את דעת ר' אליעזר כי \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 בין במשנה ובין בברייתא מדובר \u0003בעיסה\u0004 שהיתה \u0003ראשונה\u0004 לטומאה, \u0003ו\u0004עוד הניחו כי \u0003חולין הטבולין לחלה\u0004 (שהם בגדר טבל, שצריכים להפריש מהם חלה) \u0003לא כחלה דמו\u0004 \u0005[נחשבים]\u0006 לענין טהרתם, אלא כחולין גמורים.","ועל סמך הנחות אלה מציעים: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה חלוקים]\u0006 ר' אליעזר וחכמים, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003אין שני עושה שלישי בחולין,\u0004 ולכן גם אם מניח בצק טהור ששיעורו כביצה באמצע, ועל ידי כך נטמאת החתיכה מחמת העיסה הטמאה ונעשית שני לטומאה, מכל מקום אינה יכולה לטמא את העיסה האחרת, שאין שני עושה שלישי בחולין.","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003שני עושה שלישי בחולין,\u0004 ולכן אוסרים לחבר את העיסה הטמאה והטהורה.","\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 אפשר לומר ש\u0003אין שני עושה שלישי בחולין, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004ענין \u0003חולין הטבולין לחלה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003כחלה דמו\u0004 \u0005[נחשבים]\u0006 וחלה דינה כתרומה, ששני לטומאה פוסל את השלישי ולכן הם אוסרים, \u0003ומר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003לא כחלה דמו\u0004 \u0005[נחשבים],\u0006 ומתיר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003חולין הטבולין לחלה לא כחלה דמו\u0004 \u0005[נחשבים]\u0006 \u0003ואין שני עושה שלישי בחולין והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אחרת, האם \u0003מותר לגרום טומאה לחולין שבארץ ישראל קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003מותר לגרום טומאה לחולין שבארץ ישראל,\u0004 ולכן יכול לתת באמצע אפילו כביצה מעיסה טהורה ואינו חושש במה שהיא נטמאת, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003אסור לגרום טומאה לחולין שבארץ ישראל.\u0004","שנינו במשנה: \u0003בו ביום דרש רבי עקיבא\u0004 לגבי תחום שבת, שלמד הלכות אלה מדין ערי הלויים, ור' אליעזר בנו של ר' יוסי הגלילי דרש את הפסוק לענין אחר.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005חלוקים\u0006 הם\u0005]?\u0006 ומשיבים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003תחומין\u0004 של שבת \u0003דאורייתא\u0004 \u0005[מן התורה\u0006 הם\u0005],\u0006 ומוצא לכך ראיה בכתוב, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר בנו של ר' יוסי הגלילי, \u0005סבור]\u0006 שתחומים הם רק \u0003דרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים],\u0006 ולכן דורש את הפסוק לענין אחר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בו ביום דרש ר' עקיבא: בשעה שעלו ישראל מן הים, נתנו עיניהם\u0004 (החליטו) \u0003לומר שירה. וכיצד אמרו שירה —\u0004 \u0003כגדול המקרא את הלל\u0004 ומוציא את הרבים ידי חובה, \u0003והן\u0004 הקהל \u0003עונין אחריו ראשי פרקים\u0004 של ההלל, כגון \"הודו לה' כי טוב\". כיצד? \u0003משה אמר \"אשירה לה'\"\u0004 (שמות טו, א) \u0003והן אומרים \"אשירה לה'\", משה אמר \"כי גאה גאה\" והן אומרים\u0004 אחריו שוב \u0003\"אשירה לה'\".\u0004","\u0003ר' אליעזר בנו של ר' יוסי הגלילי אומר:\u0004 ישראל קראו את השירה \u0003כ\u0004דרך שנוהגים ב\u0003קטן המקרא את הלל, והן\u0004 הקהל, \u0003עונין אחריו כל מה שהוא אומר\u0004 לפי שאינו מוציאם ידי חובה, והם צריכים לומר הכל בעצמם. כיצד? \u0003משה אמר \"אשירה לה'\" והן אומרים \"אשירה לה'\", משה אמר \"כי גאה גאה\" והן אומרים \"כי גאה גאה\".\u0004","\u0003ר' נחמיה אומר:\u0004 נהגו \u0003כסופר\u0004 (חזן) \u0003הפורס\u0004 (פותח) \u0003על\u0004 ברכות קריאת \u0003שמע בבית הכנסת, שהוא פותח תחילה\u0004 ואומר את המילים הראשונות של הברכה \u0003והן עונין אחריו\u0004 ומשלימים.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 — \u0003ר' עקיבא סבר: \"לאמר\"\u0004 (שמות טו, א), המבטא חזרה על מה שנאמר, מתייחס רק \u0003אמילתא קמייתא\u0004 \u0005[על הדבר הראשון]\u0006 \"אשירה לה\"', שהוא שנאמר על ידי הכל.","\u0003ור' אליעזר בנו של ר' יוסי הגלילי סבר: \"לאמר\" —\u0004 \u0003אכל מילתא ומילתא\u0004 \u0005[על כל דבר ודבר].\u0006 \u0003ור' נחמיה סבר: \"ויאמרו\"\u0004 (שמות טו, א) כוונתו — \u0003דאמור כולהו בהדי הדדי\u0004 \u0005[שאמרו כולם יחד],\u0006 ואילו \u0003\"לאמר\"\u0004 בא לומר ש\u0003פתח משה ברישא\u0004 \u0005[בתחילה]\u0006 ורק אחר כך השלימו כולם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003דרש ר' יוסי הגלילי: בשעה שעלו ישראל מן הים נתנו עיניהם\u0004 (החליטו) \u0003לומר שירה. וכיצד אמרו שירה? עולל מוטל על ברכי אמו, ותינוק יונק משדי אמו, כיון שראו את השכינה —\u0004 \u0003עולל הגביה צוארו, ותינוק שמט דד מפיו, ואמרו \"זה אלי ואנוהו\"\u0004 (שמות טו, ב), \u0003שנאמר:\u0004 \u0003\"מפי עוללים ויונקים יסדת עז\"\u0004 (תהלים ח, ג).","\u0003היה ר' מאיר אומר: מנין שאפילו עוברים שבמעי אמן אמרו שירה\u0004 על הים — \u0003שנאמר\u0004 על שירת הים"],["\u0003\"במקהלות ברכו אלהים ה' ממקור ישראל\"\u0004 (תהלים סח, כז) שגם מן הרחם (\"מקור\") ברכו את ה' כשנקהלו (\"במקהלות\") על הים.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 העוברים במעי אמם \u0003לא חזו\u0004 \u0005[ראו],\u0006 ואיך אמרו \"זה אלי ואנווהו\"? \u0003אמר ר' תנחום: כרס\u0004 של אמם \u0003נעשה להן כאספקלריא המאירה\u0004 (כזכוכית שקופה) \u0003וראו\u0004 דרכה.","שנינו במשנה: \u0003בו ביום דרש ר' יהושע בן הורקנוס\u0004 ש\u0003לא\u0004 \u0003עבד איוב\u0004 את הקדוש ברוך הוא אלא מאהבה, והביא ראיה מן הכתוב \"הן יקטלני לו איחל\" (איוב יג, טו), ועדיין נשאר בספק בגלל אי הבהירות במשמעות \"לו\". ושואלים: \u0003וליחזי\u0004 \u0005[ושיראה]\u0006 \u0003האי\u0004 \u0005[\u0006מלה \u0005זו]\u0006 \u0003\"לא\", אי בלמ\"ד אל\"ף כתיב\u0004 \u0005[כתובה]\u0006 היא, ואם כן — \u0003לא הוא, אי\u0004 \u0005[אם]\u0006 \u0003בלמ\"ד וי\"ו כתיב\u0004 \u0005[כתובה]\u0006 היא ואם כן \u0003לו הוא?\u0004","על כך מקשים: \u0003וכל היכא דכתיב\u0004 \u0005[מקום שנאמר]\u0006 \u0003בלמ\"ד אל\"ף,\u0004 תמיד \u0003לא,\u0004 בלשון שלילה \u0003הוא? אלא מעתה \"בכל צרתם לא צר\"\u0004 (ישעיה סג, ט) \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בלמ\"ד אל\"ף, הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003\"לא\"\u0004 בלשון שלילה \u0003הוא?\u0004 \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן],\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 מיד אחר כך \u0003\"ומלאך פניו הושיעם\",\u0004 משמע שהכוונה היא \"לו\" בוי\"ו! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הצירוף \"לא\" \u0003משמע הכי ומשמע הכי\u0004 \u0005[משמעו כך ומשמעו כך]\u0006 בין לחיוב בין לשלילה, ואין להוכיח מן הכתוב. ולכן הוצרך ר' יהושע בן הורקנוס לראיה אחרת.","","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' מאיר אומר: נאמר \"ירא אלהים\"\u0004 (איוב א, א) \u0003באיוב, ונאמר \"ירא אלהים\"\u0004 (בראשית כב, יב) \u0003באברהם, מה \"ירא אלהים\" האמור באברהם —\u0004 \u0003מאהבה\u0004 עשה, \u0003אף \"ירא אלהים\" האמור באיוב —\u0004 \u0003מאהבה.\u0004","ושואלים: \u0003ואברהם גופיה מנלן\u0004 \u0005[עצמו מניין לנו]\u0006 שעשה מאהבה — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"זרע אברהם אהבי\"\u0004 (ישעיה מא, ח).","ושואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין עושה מאהבה לעושה מיראה?\u0004 ומשיבים: \u0003איכא הא דתניא\u0004 \u0005[יש\u0006 את \u0005זו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: גדול העושה מאהבה יותר מן העושה מיראה, שזה\u0004 העושה מיראה \u0003תלוי\u0004 ונשמר לו הדבר לזכות \u0003לאלף דור. וזה\u0004 העושה מאהבה \u0003תלוי לאלפים דור.\u0004","וראיה לכך: \u0003הכא כתיב\u0004 \u0005[כאן נאמר]:\u0006 \u0003\"\u0004ועושה חסד \u0003לאלפים לאהבי ולשמרי מצותי\"\u0004 (שמות כ, ו) הרי שהחסד נשמר אלפי דורות לעושה מאהבה (\"אוהבי\"), \u0003והתם כתיב\u0004 \u0005[ושם נאמר]:\u0006 \u0003\"ולשמרי מצותו לאלף דור\"\u0004 (דברים ז, ט).","ומקשים: \u0003התם נמי כתיב\u0004 \u0005[שם גם כן נאמר]\u0006 \u0003\"לאהביו ולשמרי מצותו לאלף דור\"\u0004 (דברים ז, ט)!","ומשיבים: \u0003האי לדסמיך ליה והאי לדסמיך ליה\u0004 \u0005[זה\u0006 (אלפיים) מתייחס \u0005לשסמוך לו\u0006 (\"אוהביו\") \u0005וזה\u0006 (אלף) \u0005מתייחס לשסמוך לו\u0006 (\"שומרי מצוותיו\")\u0005]\u0006.","מסופר: \u0003הנהו תרי תלמידי דהוו יתבי קמיה\u0004 \u0005[אלו שני התלמידים שהיו יושבים לפני]\u0006 \u0003רבא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אקריון בחלמאי\u0004 \u0005[הקריאו לי בחלומי]\u0006 פסוק זה: \u0003\"מה רב טובך אשר צפנת ליראיך\"\u0004 (תהלים לא, כ), \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אקריון בחלמאי\u0004 \u0005[הקריאו לי בחלומי]\u0006 \u0003\"וישמחו כל חוסי בך לעולם ירננו\u0004 ותסך עלימו \u0003ויעלצו בך אהבי שמך\"\u0004 (תהלים ה, יב). \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תרוייכו רבנן צדיקי גמורי אתון\u0004 \u0005[שניכם חכמים צדיקים גמורים אתם]\u0006 אלא \u0003מר\u0004 \u0005[חכם זה]\u0006 עובד את ה' \u0003מאהבה, ומר\u0004 \u0005[וחכם זה]\u0006 עובד את ה' \u0003מיראה.\u0004","","\u0003מי שקינא לאשתו ונסתרה, אפילו שמע מעוף הפורח,\u0004 כלומר, מכל מקור שהוא, שנסתרה — \u0003יוציא\u0004 (יגרש אותה), \u0003ויתן כתובה,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 \u0003ר' יהושע אומר:\u0004 אין מגרש אותה \u0003עד שישאו ויתנו בה\u0004 ויספרו עליה \u0003מוזרות בלבנה\u0004 (נשים היושבות וטוות לאור הירח) ובדרך אגב מדברות ברכילות של העיר.","","אם \u0003אמר עד אחד \"אני ראיתיה שנטמאת\" —\u0004 \u0003לא היתה שותה\u0004 אלא מגרשה. \u0003ולא עוד אלא אפילו עבד אפילו שפחה\u0004 שאינם נאמנים לעדות — \u0003הרי אלו נאמנין\u0004 לענין עדות טומאה \u0003אף לפוסלה מכתובתה\u0004 שנחשבת כזונה ומאבדת כתובתה.","\u0003חמותה ובת חמותה וצרתה ויבמתה\u0004 (גיסתה, אשת אחיה) \u0003ובת בעלה,\u0004 אף שהן חשודות ואינן נאמנות להעיד על האשה בדרך כלל — \u0003הרי אלו נאמנות\u0004 להעיד עליה בענין זה. \u0003ולא\u0004 שהאמינו להן \u0003לפוסלה מכתובתה,\u0004 שאין עדותן מועילה לכך, \u0003אלא\u0004 ש\u0003לא תשתה.\u0004","שלכאורה \u0003שהיה בדין\u0004 לומר אחרת: \u0003ומה אם עדות ראשונה\u0004 שנסתרה \u0003שאין אוסרתה איסור עולם\u0004 אלא נבדקת במי סוטה — \u0003אינה מתקיימת בפחות משנים\u0004 שצריכים שני עדים שיעידו שנסתרה, \u0003עדות אחרונה\u0004 שנטמאה \u0003שאוסרתה איסור עולם —\u0004 \u0003אינו דין\u0004 ש\u0003לא תתקיים בפחות משנים?\u0004 — \u0003תלמוד לומר: \"ועד אין בה\"\u0004 (במדבר ה, יג) \u0003כל עדות שיש בה.\u0004","","ואפשר להקשות: אם כן נעשה \u0003קל וחומר לעדות הראשונה\u0004 מתוך הלכה זו \u0003מעתה: ומה אם\u0004"],["\u0003עדות אחרונה\u0004 על הטומאה \u0003שאוסרתה איסור עולם —\u0004 \u0003הרי היא מתקיימת בעד אחד\u0004 בלבד, \u0003עדות הראשונה\u0004 על הסתירה \u0003שאין אוסרתה איסור עולם\u0004 אלא עד שתשתה — \u0003אינו דין שתתקיים בעד אחד?\u0004","\u0003תלמוד לומר: \"כי מצא בה ערות דבר\"\u0004 (דברים כד, א) \u0003ולהלן הוא אומר \"על פי שני עדים... יקום דבר\"\u0004 (דברים יט, טו), ולמדים מגזירה שווה \"דבר\" \"דבר\" \u0003מה להלן\u0004 אין הדבר מתקיים אלא \u0003על פי שנים —\u0004 \u0003אף כאן\u0004 אין עדות על הסתירה אלא על \u0003פי שנים.\u0004","היה \u0003עד\u0004 אחד \u0003אומר \"נטמאת\" ועד\u0004 אחר \u0003אומר \"לא נטמאת\", אשה\u0004 אחת \u0003אומרת \"נטמאת\" ואשה\u0004 אחרת \u0003אומרת \"לא נטמאת\" —\u0004 \u0003היתה שותה,\u0004 שמאחר שיש עדויות הסותרות זו את זו — הרי זה ספק אם נטמאת ושותה.","\u0003אחד אומר \"נטמאת\" ושנים אומרים \"לא נטמאת\" —\u0004 \u0003היתה שותה. שנים אומרים \"נטמאת\" ואחד אומר \"לא נטמאת\"\u0004 — סומכים על עדות השנים, ו\u0003לא היתה שותה\u0004 אלא יוצאת מבעלה.","על הלימוד מהגזירה שווה הנמצא במדרש ההלכה במשנה זו, שאין עדות על קינוי וסתירה בפחות משני עדים, שואלים: \u0003האי\u0004 \u0005[זה]\u0006 \u0003תלמוד לומר \"כי מצא בה ערות דבר\",\u0004 הלא לכאורה","\u0003תלמוד לומר\u0004 בפרשת סוטה \u0003\"בה\"\u0004 (\"והיא נטמאה ועד אין בה\" — במדבר ה, יג) ומהדיוק \u0003בה ולא בקינוי, בה ולא בסתירה מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי מכאן למדנו דין עד אחד בטומאה!","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כך צריך להבין את הדברים: \u0003תלמוד לומר \"בה\" —\u0004 \u0003בה ולא בקינוי, בה ולא בסתירה.\u0004","\u0003ו\u0004אולם \u0003טומאה בעלמא\u0004 \u0005[סתם]\u0006 שמעיד אדם על אשת איש שנטמאה \u0003בלא קינוי ובלא סתירה,\u0004 ש\u0003לא מהימן\u0004 \u0005[נאמן]\u0006 \u0003עד אחד מנלן\u0004 \u0005[מניין לנו]?\u0006 — דין זה נלמד באופן אחר, \u0003נאמר כאן\u0004 בענין עדות \u0003\"דבר\", ונאמר להלן \"דבר\"\u0004 בענין ערוה, \u0003מה להלן\u0004 מדובר \u0003ב\u0004עדות \u0003שני עדים —\u0004 \u0003אף כאן בשני עדים,\u0004 ואין עד אחד מספיק לכך.","שנינו במשנה: \u0003עד אומר נטמאת\u0004 ועד אומר לא נטמאת — היתה שותה. ומעירים: יש לדייק, \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דקא מכחיש ליה\u0004 \u0005[שמכחיש אותו]\u0006 העד השני, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא קא מכחיש ליה\u0004 \u0005[\u0006היה \u0005מכחיש אותו]\u0006 היה \u0003עד אחד מהימן\u0004 \u0005[נאמן]\u0006 ואסורה על בעלה לעולם,","\u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 ומביאים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 מה שנאמר \u0003\"ועד אין בה\"\u0004 (במדבר ה, יג) — \u0003בשנים הכתוב מדבר,\u0004 שאם אין בה שני עדים, אלא עד אחד בלבד, הרי היא אסורה.","\u0003אתה אומר בשנים, או אינו אלא באחד? —\u0004 \u0003תלמוד לומר: \"לא יקום עד אחד באיש\u0004 לכל עוון ולכל חטאת\u0003\"\u0004 (דברים יט, טו","\u0003), ועל כך דרשו:\u0004 \u0003ממשמע שנאמר\u0004 \u0003\"לא יקום עד\" איני יודע שהוא אחד,\u0004 שהרי לשון יחיד הוא, \u0003מה תלמוד לומר \"אחד\" —\u0004 \u0003זה בנה אב\u0004 וקבע תקדים ויסוד להלכה: \u0003כל מקום שנאמר\u0004 \u0003\"עד\" —\u0004 \u0003הרי כאן שנים, עד שיפרוט לך הכתוב\u0004 ויאמר במפורש \u0003\"אחד\". ו\u0004אם כן גם כאן בענין סוטה","\u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 אם \u0003תרי לית\u0004 \u0005[שני\u0006 עדים \u0005אין]\u0006 \u0003בה אלא חד\u0004 \u0005[\u0006עד \u0005אחד]\u0006 \u0003\"והיא לא נתפשה\"\u0004 (נאנסה) (במדבר ה, יג) — הריהי \u0003אסורה.\u0004","ושואלים: \u0003וכיון דמדאורייתא\u0004 \u0005[שמ\u0006 דין \u0005תורה]\u0006 \u0003עד אחד מהימן\u0004 \u0005[נאמן],\u0006 אם כן \u0003אידך היכי מצי מכחיש ליה\u0004 \u0005[האחר איך יכול להכחיש אותו]\u0006 ולגרום לה שתשתה ולא תיאסר עולמית בעדות הראשון? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר עולא: כל מקום שהאמינה תורה עד אחד\u0004 לעדות \u0003הרי כאן\u0004 עדות כעדות \u0003שנים, ואין דבריו של\u0004 עד \u0003אחד\u0004 קיימים \u0003במקום\u0004 שהוא סותר \u0003שנים!\u0004","\u0003אלא אמר עולא: תני\u0004 \u0005[שנה,\u0006 ותקן במשנתנו\u0005]:\u0006 עד אומר נטמאת ועד אומר לא נטמאת — \u0003לא היתה שותה. וכן אמר ר' יצחק,\u0004 יש לשנות: \u0003לא היתה שותה. ור' חייא אמר\u0004 שהנוסח הוא: \u0003היתה שותה.\u0004","ושואלים: \u0003לר' חייא קשיא\u0004 \u0005[קשה]\u0006 מה שהיה קשה ל\u0003עולא:\u0004 והרי דינו של העד הראשון כשניים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 במשנתנו מדובר שבאו שני העדים \u0003בבת אחת,\u0004 וכיון שהם סותרים זה את זה — הרי זה כאילו לא היתה כאן עדות. ואילו \u0003כאן,\u0004 בדין של עולא, מדובר שבאו \u0003בזה אחר זה,\u0004 כשבא עד אחד והעיד שנטמאה מקובלת עדותו כעדות של שניים ואין השני יכול לבטל עדותו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003עד\u0004 אחד \u0003אומר \"נטמאת\" ושנים אומרים \"לא נטמאת\" —\u0004 \u0003היתה שותה,\u0004 ונדייק מכאן: \u0003הא חד וחד\u0004 \u0005[הרי\u0006 אם היו \u0005אחד ואחד]\u0006 — \u0003לא היתה שותה,\u0004 אם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא על \u0003ר' חייא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' חייא: וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה מדייק, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003שנים אומרים \"נטמאת\" ואחד אומר \"לא נטמאת\" —\u0004 \u0003לא היתה שותה.\u0004 ותדייק מכאן: \u0003הא חד וחד\u0004 \u0005[הרי\u0006 אם היו \u0005אחד ואחד]\u0006 — \u0003היתה שותה.\u0004 ונמצא כי הדיוק הראשון והאחרון סותרים זה את זה!","\u0003אלא\u0004 גם לשם תירוץ המשנה צריכים לומר שאין לדייק כך, אלא \u0003כולה בפסולי עדות\u0004 היא מדברת, שהשניים שבאו להעיד הם פסולי עדות שמקבלים את עדותם בסוטה, \u0003ו\u0004שיטת \u0003ר' נחמיה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה תורה עד אחד\u0004 ואין התורה דורשת שם עדות כשירה דווקא — \u0003הלך\u0004 (לך) \u0003אחר רוב דעות, ועשו\u0004 עדות \u0003שתי נשים ב\u0004יחס לעדות \u0003איש אחד כ\u0004עדות \u0003שני אנשים באיש אחד,\u0004 שסומכים על השניים נגד האחד.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שיטה אחרת כדעת ר' נחמיה: \u0003כל היכא דאתא\u0004 \u0005[מקום שבא]\u0006 \u0003עד אחד כשר מעיקרא\u0004 \u0005[מתחילה] —\u0006 \u0003אפילו מאה נשים\u0004 המעידות כנגדו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003כעד אחד\u0004 בלבד \u0003דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 ואינן יכולות לבטל את עדותו."],["\u0003והכא\u0004 \u0005[וכאן]\u0006 שעד אומר \"נטמאת\" ושנים אומרים \"לא נטמאת\", ששותה, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים] —\u0006 \u0003כגון דאתאי\u0004 \u0005[שבאה]\u0006 \u0003אשה מעיקרא\u0004 \u0005[מתחילה]\u0006 שאין עדותה נחשבת כשניים. \u0003ותרצה לדר' נחמיה הכי\u0004 \u0005[ותקן\u0006 והסבר \u0005את\u0006 דברי \u0005ר' נחמיה כך],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה תורה עד אחד —\u0004 \u0003הלך\u0004 (לך) \u0003אחר רוב דעות, ועשו\u0004 עדות \u0003שתי נשים ב\u0004יחס לעדות \u0003אשה אחת כ\u0004עדות \u0003שני אנשים באיש אחד\u0004 ומבטלות את עדות האשה האחת. \u0003אבל\u0004 עדות \u0003שתי נשים באיש אחד —\u0004 \u0003כי פלגא ופלגא דמי\u0004 \u0005[כמו חצי וחצי נחשבים]\u0006 שעדותן של שתי נשים נחשבת כעדות של איש אחד.","","ושואלים: אם זה פירוש המשנה \u0003ותרתי\u0004 \u0005[ושתי]\u0006 הלכות \u0003בפסולי עדות למה לי?\u0004 ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי אזלינן בתר\u0004 \u0005[כאשר אנו הולכים אחר]\u0006 \u0003רוב דעות\u0004 הרי זה רק \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 עליה שתשתה, כגון אם אמר אחד שנטמאה ושנים אומרים שלא נטמאה, \u0003אבל לקולא\u0004 \u0005[להקל]\u0006 ולפטור אותה משתיה, כגון אם אמרו שתי נשים שנטמאה ועד אחד פסול אומר שלא נטמאה \u0003לא אזלינן\u0004 \u0005[אין אנו הולכים]\u0006 אחר רוב פסולים, ותשתה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשנה שהולכים אחר רוב דיעות, בין להקל בין להחמיר.","","\u0003אלו נאמרין בכל לשון\u0004 ולאו דווקא בלשון הקודש: \u0003פרשת סוטה,\u0004 כאשר הכהן מזהיר ומשביע אותה, \u0003ווידוי מעשר\u0004 שאדם מתוודה לאחר שלוש שנים של מחזור השמיטה, שהפריש את כל מעשרותיו כתיקונם, \u0003קרית\u0004 (קריאת) \u0003שמע, ותפלה, וברכת המזון, ושבועת העדות,\u0004 שנשבע אדם שאין לו מה להעיד בנושא מסויים, \u0003ושבועת הפיקדון\u0004 שנשבע לחבירו שאין בידו פיקדון שלו.","\u0003ואלו\u0004 הדברים \u0003נאמרין בלשון הקודש\u0004 דווקא: \u0003מקרא ביכורים,\u0004 פסוקים שצריך אדם לומר כשמביא את הביכורים למקדש, \u0003ו\u0004מה שאומרים היבם והיבמה ב\u0003חליצה, ברכות וקללות\u0004 שאמרו בהר גריזים ובהר עיבל, \u0003ברכת כהנים, וברכת כהן גדול\u0004 על התורה ביום הכיפורים, \u0003ופרשת המלך\u0004 שמקריא במעמד הקהל, \u0003ופרשת עגלה ערופה,\u0004 מה שאומרים בשעה שעורפים את העגלה בנחל אם נמצא הרוג שלא נודע רוצחו. \u0003ומשוח מלחמה בשעה שמדבר אל העם\u0004 לפני היציאה למלחמה.","\u0003מקרא ביכורים כיצד\u0004 יודעים אנו שנאמר דווקא בלשון הקודש? — שנאמר בפרשת הביכורים: \u0003\"וענית ואמרת לפני ה' אלהיך\"\u0004 (דברים כו, ה) ו\u0003להלן\u0004 בברכות וקללות \u0003הוא אומר \"וענו הלוים ואמרו\"\u0004 (דברים כז, יד), \u0003מה להלן\u0004 בדברי הלויים ענייה היא \u0003בלשון הקודש\u0004 דווקא — \u0003אף כאן\u0004 בביכורים \u0003בלשון הקודש.\u0004","\u0003חליצה כיצד\u0004 אנו יודעים שמה שנאמר בה צריך להיות בלשון הקודש דווקא? — שנאמר: \u0003\"וענתה ואמרה\"\u0004 (דברים כה, ט) \u0003ולהלן הוא אומר \"וענו הלוים ואמרו\"\u0004 (דברים כז, יד) — \u0003מה להלן בלשון הקודש\u0004 דווקא — \u0003אף כאן בלשון הקודש.\u0004","\u0003ר' יהודה אומר,\u0004 הדבר נלמד באופן אחר; נאמר \u0003\"וענתה ואמרה ככה\"\u0004 (דברים כה, ט) ו\"ככה\" בא לדייק: \u0003עד שתאמר בלשון הזה\u0004 שנאמרה בכתוב בדיוק.","\u0003ברכות וקללות כיצד\u0004 נעשו? — \u0003כיון שעברו ישראל את הירדן ובאו אל הר גריזים ואל הר עיבל שבשומרון, שבצד שכם, שבאצל אלוני מורה. שנאמר: \"הלא המה בעבר הירדן...\u0004 אצל אלוני מורה \u0003\"\u0004\u0003(דברים יא, ל),\u0004 \u0003ולהלן הוא אומר \"ויעבר אברם בארץ עד מקום שכם עד אלון מורה\"\u0004 (בראשית יב, ו), \u0003מה אלון מורה האמור להלן\u0004 באברהם — סמוך ל\u0003שכם, אף אלון מורה האמור כאן —\u0004 \u0003שכם.\u0004","\u0003ששה שבטים עלו לראש הר גריזים וששה שבטים עלו לראש הר עיבל, והכהנים והלוים והארון עומדים למטה באמצע\u0004 בין שני ההרים, \u0003הכהנים מקיפין את הארון\u0004 מסביב \u0003והלוים\u0004 מקיפים \u0003את הכהנים, וכל ישראל\u0004 עומדים על ההרים \u0003מכאן ומכאן, שנאמר:\u0004 \u0003\"וכל ישראל וזקניו ושטריו ושפטיו עמדים מזה ומזה לארון\"\u0004 (יהושע ח, לג).","\u0003הפכו\u0004 הלויים \u0003פניהם כלפי הר גריזים ופתחו בברכה,\u0004 ומה ברכו: \u0003\"ברוך האיש אשר לא יעשה פסל ומסכה\"\u0004 (ראה דברים כז, טו), \u0003ואלו ואלו,\u0004 העומדים על שני ההרים, \u0003עונין \"אמן\".\u0004 אחר כך \u0003הפכו פניהם כלפי הר עיבל ופתחו בקללה: \"ארור האיש אשר יעשה פסל ומסכה\"\u0004 (דברים כז, טו), \u0003ואלו ואלו עונין \"אמן\", עד שגומרין ברכות וקללות.\u0004","\u0003ואחר כך הביאו את האבנים,\u0004 כמצווה עליהם בתורה, \u0003ובנו את המזבח, וסדוהו בסיד, וכתבו עליו את כל דברי התורה בשבעים לשון. שנאמר:\u0004 \u0003\"באר היטב\"\u0004 (דברים כז, ח), שהכוונה — מבואר בכל הלשונות. \u0003ונטלו\u0004 לאחר מכן \u0003את האבנים\u0004 משם, \u0003ובאו\u0004"],["\u0003ולנו במקומן\u0004 בגלגל.","\u0003פרשת סוטה מנלן\u0004 \u0005[מניין לנו]\u0006 שנאמרת בכל לשון? — \u0003דכתיב,\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואמר הכהן לאשה\"\u0004 (במדבר ה, כא) כוונתו — \u0003בכל לשון שהוא אומר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משמיעין אותה\u0004 את הסוטה, \u0003בכל לשון שהיא שומעת, על מה היא שותה, ובמה היא שותה. על מה נטמאת, ובמה היא נטמאת.\u0004","ופרטי הדברים: \u0003על מה,\u0004 באיזה סיבה, \u0003היא שותה —\u0004 \u0003על עסקי קינוי וסתירה, ובמה היא שותה —\u0004 \u0003במקידה\u0004 (כלי פשוט) \u0003של חרש.\u0004","\u0003על מה\u0004 היא \u0003נטמאת —\u0004 \u0003על עסקי שחוק וילדות. ובמה היא נטמאת\u0004 שצריכים להסביר לה — שיש הבדל אם נטמאה \u0003בשוגג או במזיד. באונס [או] ברצון. וכל כך למה\u0004 מרבים להסביר לה — כדי ש\u0003לא להוציא לעז על מים המרים,\u0004 כדי שתדע שאם חטאה באונס או בשוגג אין המים בודקים אותה.","\u0003וידוי מעשר מנלן\u0004 \u0005[מניין לנו]\u0006 שהוא בכל לשון? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואמרת לפני ה' אלהיך בערתי הקדש מן הבית\"\u0004 (דברים כו, יג), \u0003ויליף\u0004 \u0005[ולומד]\u0006 בגזירה שווה \u0003\"אמירה\"\u0004 \"אמירה\" \u0003מסוטה\u0004 — לומר שאף וידוי מעשר נאמר בכל לשון שהוא אומר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב זביד לאביי: ולילף\u0004 \u0005[ושילמד]\u0006 \u0003אמירה מלוים,\u0004 ויאמר כך: \u0003מה להלן\u0004 בלויים, ברכות וקללות שאמרו, היה זה \u0003בלשון הקודש אף כאן בלשון הקודש!\u0004","ענה לו אביי: \u0003דנין\u0004 מקום שנאמרה בו לשון \u0003\"אמירה\" גרידתא\u0004 \u0005[בלבד]\u0006 \u0003מ\u0004מקום שנאמרה בו \u0003\"אמירה\" גרידתא\u0004 \u0005[בלבד],\u0006 \u0003ואין דנין\u0004 מקום שנאמרה בו \u0003\"אמירה\" גרידתא\u0004 \u0005[בלבד],\u0006 כגון וידוי מעשר, \u0003מ\u0004מקום שנאמר בו \u0003\"ענייה\" ו\"אמירה\"\u0004 (\"וענו הלויים ואמרו\". דברים כז, יד), שיש לכך משמעות מיוחדת.","שכך \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר:\u0004 ראוי שיהא \u0003אדם אומר שבחו\u0004 של עצמו \u0003בקול נמוך וגנותו בקול רם.\u0004","ולמדים שאומר \u0003שבחו בקול נמוך מן וידוי המעשר\u0004 שלא נאמרה בו לשון \"וענית\", ובוידוי זה אומר שעשה הכל כראוי. \u0003גנותו בקול רם —\u0004 \u0003ממקרא ביכורים,\u0004 ששם מספרים על מאורעות וצרות שאירעו לאומה ובגנות לבן הארמי שמוצאנו ממנו, ושם נאמר \"וענית ואמרת\" שהכוונה לקול רם.","ומקשים: \u0003וגנותו\u0004 אומר אדם \u0003בקול רם?! והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי\u0004 עצמו: \u0003מפני מה תקנו תפלה בלחש —\u0004 \u0003כדי\u0004 ש\u0003לא לבייש את עוברי עבירה\u0004 שמתוודים על חטאיהם בשעת התפלה. וראיה לדבר שאין מביישים אותם, \u0003שהרי לא חלק\u0004 (הבדיל) \u0003הכתוב מקום\u0004 שונה לעבודת הקרבן \u0003בין חטאת לעולה,\u0004 כדי שלא יהא ניכר שהוא חוטא ומביא חטאת ולא יתבייש בכך, ומכאן שגם גנותו אומר בלחש!","ומתקנים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003גנותו\u0004 בקול רם, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003צערו\u0004 בקול רם. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"וטמא טמא יקרא\"\u0004 (ויקרא יג, מה) — \u0003צריך\u0004 המצורע \u0003להודיע צערו לרבים\u0004 שהוא טמא, \u0003ורבים מבקשים עליו רחמים. ו\u0004כן \u0003כל מי שאירע בו דבר\u0004 של צער \u0003צריך להודיע לרבים, ורבים מבקשים עליו רחמים.\u0004","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של אותה מימרה ש\u0003אמר ר' יוחנן משום\u0004 \u0003ר' שמעון בן יוחי: מפני מה תיקנו תפלה בלחש —\u0004 כדי ש\u0003לא לבייש את עוברי עבירה.\u0004 וראיה לדבר: \u0003שהרי לא חלק הכתוב מקום בין חטאת לעולה.\u0004","ושואלים: \u0003ולא?\u0004 האם אין הבדל מקום? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 הבדל מקום לגבי זריקת \u0003דמים\u0004 שאינם ניתנים באותו מקום, ש\u0003דם חטאת\u0004 ניתן \u0003למעלה\u0004 ממחצית גובה המזבח, \u0003ודם עולה למטה\u0004 ממחצית גובהו! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כהן הוא דידע,\u0004 \u0005[שיודע]\u0006 אבל אחרים שאינם עומדים שם אינם יודעים.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 הבדל אחר הניכר לעין: \u0003חטאת\u0004 היא \u0003נקבה,\u0004 ו\u0003עולה\u0004 היא \u0003זכר,\u0004 ורואים אם כן לפי סוג הבהמה אם מביא חטאת או עולה! ומשיבים: \u0003התם מיכסיא\u0004 \u0005[שם\u0006 בחטאת \u0005מכוסה היא]\u0006 \u0003באליה\u0004 ואין מבחינים אם זכר או נקבה.","ומקשים: \u0003תינח\u0004 \u0005[נניח]\u0006 דבר זה לגבי \u0003כבשה\u0004 שמביא לחטאת, שכיון שיש לה אליה גדולה הריהי מכסה את איברי המין, אבל אם מביא לחטאתו \u0003שעירה\u0004 שאין לה אליה \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: אם מביא שעירה \u0003התם איהו דקא מיכסיף נפשיה,\u0004 \u0005[שם הוא שמבייש את עצמו],\u0006 \u0003דאיבעי ליה לאיתויי\u0004 \u0005[שצריך היה לו להביא]\u0006 \u0003כבשה\u0004 אם רוצה היה להסתיר את הדבר \u0003וקא מייתי\u0004 \u0005[ומביא]\u0006 \u0003שעירה\u0004 ואין לדאוג לבושתו.","ושואלים: \u0003חטאת\u0004 הבאה על \u0003עבודה זרה דלא סגי דלאו\u0004 \u0005[שלא די\u0006 בקרבן אחר \u0005שאינו]\u0006 \u0003שעירה\u0004 שהרי בחטאת זו מפורש שיש להביא שעירה דווקא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי ניכר שהוא מביא חטאת! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מכיון שהחטא חמור ביותר מוטב ש\u0003ניכסיף וניזיל כי היכי דנכפר ליה\u0004 \u0005[יתבייש וילך כדי שיתכפר לו]\u0006 חטאו גם על ידי בושתו.","\u0003קרית\u0004 (קריאת) \u0003שמע\u0004 שהיא נאמרת בכל לשון \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"שמע ישראל\"\u0004 (דברים ו, ד), ומשמעו \u0003בכל לשון שאתה שומע.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קרית שמע\u0004 נקראת \u0003ככתבה\u0004 בלשון הקדש, אלו \u0003דברי רבי. וחכמים אומרים: בכל לשון.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיו\u0004 הדברים האלה\u0003\"\u0004 (דברים ו, ו), ומשמע: \u0003בהווייתן יהו,\u0004 כפי שהם כתובים, בלשונם.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 על מה הם מבססים דבריהם? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"שמע\", והכוונה היא:\u0004 \u0003בכל לשון שאתה שומע.\u0004","ושואלים: \u0003ורבנן נמי\u0004 \u0005[וחכמים גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"והיו\"!\u0004 ומשיבים: הכתוב \u0003ההוא\u0004 בא ללמד ש\u0003לא\u0004 \u0003יקראנה למפרע,\u0004 מסוף הפרשה לתחילתה, אלא כסדר שהיא כתובה.","ושואלים: \u0003ורבי\u0004 הלכה זו ש\u0003לא\u0004 \u0003יקראנה למפרע מנליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת לו]\u0006 \u0003מ\u0004מה שיכול היה להיאמר \u0003\"דברים\"\u0004 ונאמר \u0003\"הדברים\",\u0004 לומר: הדברים האלה בצורתם זו. \u0003ורבנן\u0004 \u0005[וחכמים]:\u0006 הדיוק \u0003\"דברים\" \"הדברים\" לא משמע להו\u0004 \u0005[נשמע להם]\u0006 ואינם סבורים שאפשר ללמוד ממנו.","ושואלים: \u0003ורבי נמי\u0004 \u0005[גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"שמע\"!\u0004 ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 להלכה זו: \u0003להשמיע לאזניך מה שאתה מוציא מפיך,\u0004 שצריך אדם לשמוע את הדברים שהוא אומר, ואם אומר בלחש בלא לשמוע כלל — אינו יוצא. \u0003ורבנן סברי לה\u0004 \u0005[וחכמים סבורים\u0006 ב\u0005אותה]\u0006 הלכה \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003הקורא את שמע ולא השמיע לאזנו —\u0004 \u0003יצא,\u0004 ולכן מפרשים הם את \"שמע\" לענין השפה.","ושואלים: \u0003לימא קסבר\u0004 \u0005[\u0006האם \u0005לומר שסבור]\u0006 \u0003רבי\u0004"],["\u0003כל התורה בכל לשון נאמרה,\u0004 שיכולה להיאמר ולהיקרא בכל שפה, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 שדווקא \u0003בלשון הקודש נאמרה,\u0004 אם כן \u0003\"והיו\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 בקריאת שמע, ומשם למד רבי שנאמרת דווקא בלשון הקודש \u0003למה לי?\u0004","ודוחים: אין זו ראיה, שאפילו אם כל התורה בלשון הקודש נאמרה, מכל מקום \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 \"והיו\" להיאמר כאן במיוחד \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"שמע\",\u0004 ומכאן אפשר היה ללמוד — בכל לשון שאתה שומע, ולכן כדי להוציא ממשמעות זו של הדברים, צריך היה להדגיש \"והיו\".","ושואלים להיפך: \u0003לימא קסברי רבנן\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005סבורים חכמים]\u0006 כי \u0003כל התורה כולה בלשון קודש\u0004 דווקא \u0003נאמרה, דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003בכל לשון\u0004 נאמרה אם כן \u0003\"שמע\" דכתב רחמנא\u0004 \u0005[שכתבה תורה]\u0006 ללמד שפרשה זאת נקראת בכל לשון \u0003למה לי?\u0004","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והיו\",\u0004 וכדי להוציא משיטת רבי היה צורך להדגיש \"שמע\".","שנינו כי \u0003תפלה\u0004 נאמרת בכל לשון. והטעם הוא: תפילה \u0003רחמי\u0004 \u0005[\u0006בקשת \u0005רחמים]\u0006 \u0003היא, כל היכי דבעי מצלי\u0004 \u0005[כל אופן שרוצה\u0006 הוא \u0005מתפלל],\u0006 ושואלים:","\u0003ותפלה בכל לשון\u0004 היא נאמרת? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה: לעולם אל ישאל\u0004 (יבקש) \u0003אדם צרכיו\u0004 בתפלה \u0003בלשון ארמית,\u0004 וכפי ש\u0003אמר ר' יוחנן: כל השואל צרכיו בלשון ארמי —\u0004 \u0003אין מלאכי השרת נזקקין\u0004 (מטפלים) \u0003לו, לפי שאין מלאכי השרת מכירין\u0004 (יודעים) \u0003בלשון ארמי!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמר ר' יוחנן שאינו יכול לומר תפילתו בכל לשון — הרי זה \u0003ב\u0004תפלת \u0003יחיד\u0004 הצריך לסיוע המלאכים, ואולם \u0003הא\u0004 \u0005[זו]\u0006 ששנינו במשנה שיכול להתפלל בכל לשון — הרי זה בתפילה \u0003בצבור.\u0004","ושואלים: \u0003ו\u0004האם \u0003אין מלאכי השרת מכירין בלשון ארמי? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יוחנן כהן גדול שמע בת קול מבית קדש הקדשים שהוא אומר: נצחו טליא דאזלו לאגחא קרבא לאנטוכיא\u0004 \u0005[ניצחו הילדים,\u0006 הצעירים, \u0005שהלכו למלחמה לאנטיוכיה].\u0006 \u0003ושוב מעשה בשמעון הצדיק ששמע בת קול מבית קדש הקדשים שהוא אומר: בטילת עבידתא דאמר שנאה לאייתאה על היכלא\u0004 \u0005[בטילה הגזירה שאמר השונא להביא על ההיכל]\u0006 \u0003ונהרג גסקלגס\u0004 (גיוס קליגולה) \u0003ובטלו גזירותיו וכתבו אותה שעה\u0004 שנשמעה בת הקול, \u0003ו\u0004נמצא אחר כך ש\u0003כיוונו\u0004 בדיוק לאותה שעה שאירע הדבר. \u0003ו\u0004הרי \u0003בלשון ארמי היה אומר!\u0004","ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003בת קול שאני\u0004 \u0005[שונה]\u0006 \u0003דלאשמועי עבידא\u0004 \u0005[שלהשמיע\u0006 היא \u0005עשויה]\u0006 ומדברת גם בלשון ארמית, ואולם אינה שומעת אלא בלשון הקודש. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 המלאך \u0003גבריאל הוה\u0004 \u0005[היה]\u0006 זה. ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 על יוסף: \u0003בא גבריאל ולימדו שבעים לשון,\u0004 ודווקא הוא בקי בכל הלשונות, אבל לא שאר המלאכים.","שנינו כי \u0003ברכת המזון\u0004 נאמרת בכל לשון. ומקור הדבר: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ואכלת ושבעת וברכת את ה' אלהיך\"\u0004 (דברים ח, י), משמע — \u0003בכל לשון שאתה מברך.\u0004","\u0003שבועת העדות\u0004 נאמרת בכל לשון. ומקור הדבר, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באותו ענין: \u0003\"ונפש כי תחטא ושמעה קול אלה\"\u0004 (ויקרא ה, א) והדגש על השמיעה כוונתו — \u0003בכל לשון שהיא שומעת.\u0004","\u0003שבועת הפקדון\u0004 מניין לנו שנאמרת בכל לשון — \u0003אתיא\u0004 \u0005[בא,\u0006 \u0003נלמד\u0004\u0005]\u0006 הדבר בגזירה שווה \u0003\"תחטא\"\u0004 (ויקרא ה, א) \u0003\"תחטא\"\u0004 (ויקרא ה, כא) \u0003משבועת העדות.\u0004","שנינו \u0003ואלו נאמרים בלשון הקודש: מקרא ביכורים וחליצה כו', עד מקרא ביכורים כיצד\u0004 למדים? נאמר בפרשת ביכורים \u0003\"וענית ואמרת לפני ה' אלהיך\"\u0004 (דברים כו, ה) \u0003ולהלן\u0004 בברכות וקללות \u0003הוא אומר \"וענו הלוים ואמרו אל כל איש ישראל\"\u0004 (דברים כז, יד) \u0003מה \"ענייה\" האמורה להלן בלשון הקודש\u0004 דווקא — \u0003אף כאן בלשון הקודש.\u0004","ושואלים: \u0003ולוים גופייהו מנלן\u0004 \u0005[עצמם מניין לנו]\u0006 שבלשון הקודש דווקא? ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"קול\" \"קול\" ממשה, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"קול רם\"\u0004 (דברים כז, יד) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"משה ידבר והאלהים יעננו בקול\"\u0004 (שמות יט, יט), \u0003מה להלן\u0004 עשרת הדברות היו \u0003בלשון הקודש, אף כאן\u0004 דברי הלויים \u0003בלשון הקודש.\u0004","שנינו: \u0003חליצה כיצד\u0004 למדים שמה שנאמר בה הוא דווקא בלשון הקודש — שנאמר \"וענתה ואמרה\", ור' יהודה לומד את הדבר ממה שנאמר שם \"וענתה ואמרה ככה\". ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם לומדים זאת מ\"ככה\", \u0003האי\u0004 \u0005[אותו]\u0006 \u0003\"ככה\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי להו\u0004 \u0005[צריכים\u0006 הם \u0005אותו]\u0006 להלכה אחרת, ללמד \u0003לדבר שהוא מעשה\u0004 ש\u0003מעכב\u0004 בחליצה, שכן נאמר שם \"ככה יעשה\", אבל מה שאיננו מעשה, כגון הדיבור בלבד — אינו מעכב והחליצה כשירה בדיעבד.","\u0003ור' יהודה\u0004 לומד דבר זה \u0003מ\u0004מה שיכול היה לכתוב \u0003\"כה\",\u0004 ואמר \u0003\"ככה\"\u0004 והרי זו לשון מיעוט כפולה. ו\u0003רבנן\u0004 \u0005[חכמים],\u0006 הדיוק של \u0003\"כה\" \"ככה\" לא משמע להו\u0004 \u0005[נשמע להם]\u0006 כדבר שאפשר ללמוד ממנו."],["\u0003ור' יהודה, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"וענתה ואמרה\"\u0004 שחכמים למדים ממנו ללשון הקודש, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה לאגמורי\u0004 \u0005[צריך אותו\u0006 כדי \u0005ללמד]\u0006 \u0003ל\u0004ענין ה\u0003לוים,\u0004 ש\u0003בלשון הקודש\u0004 הם אומרים. שהוא לומד גזירה שווה הפוכה, מדין יבמה לענין הלויים.","ושואלים: \u0003ולילף\u0004 \u0005[ושילמד]\u0006 בגזירה שווה \"קול\" \u0003\"קול\" ממשה?\u0004 ומשיבים: גזירה שווה זו של \u0003\"ענייה\" \"ענייה\" גמיר\u0004 \u0005[למד,\u0006 קיבל מרבו\u0005],\u0006 גזירה שווה זו של \u0003\"קול\" \"קול\" לא גמיר\u0004 \u0005[למד],\u0006 לא קיבל מרבו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יהודה אומר: כל מקום שנאמר \"כה\"\u0004 או \u0003\"ככה\",\u0004 או לשון \u0003\"ענייה\"\u0004 או לשון \u0003\"אמירה\" —\u0004 \u0003אינו אלא לשון הקודש; \"כה\"\u0004 האמור בברכת כהנים \u0003\"כה תברכו\u0004 את בני ישראל\u0003\"\u0004 (במדבר ו, כג), \u0003\"ככה\"\u0004 (דברים, כה, ט) שנאמר ב\u0003חליצה, \"ענייה\" ו\"אמירה\"\u0004 של ה\u0003לוים.\u0004","שנינו במשנה: \u0003ברכות וקללות כיצד? כיון שעברו ישראל את הירדן כו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כשהיו בני ישראל בעבר הירדן המזרחי נאמר להם כי הר גריזים והר עיבל \u0003\"הלא המה בעבר הירדן\"\u0004 (דברים יא, ל), \u0003מעבר לירדן\u0004 מערבה \u0003ואילך\u0004 (והלאה), אלו \u0003דברי ר' יהודה. \"אחרי דרך מבוא השמש\"\u0004 (דברים יא, ל) — \u0003מקום שחמה זורחת,\u0004 כלומר, בריחוק מהירדן שבמזרח.","\u0003\"בארץ הכנעני הישב בערבה\"\u0004 (דברים יא, ל) — \u0003אלו הר גריזים והר עיבל, שיושבין בהם כותיים\u0004 (שומרונים) בזמן הזה. \u0003\"מול הגלגל\"\u0004 — כוונתו \u0003סמוך לגלגל, \"אצל אלוני מרה\"\u0004 — הרי זה \u0003שכם. ו\u0004כיצד אנו יודעים? — \u0003להלן הוא אומר \"ויעבר אברם בארץ עד מקום שכם עד אלון מורה\"\u0004 (בראשית יב, ו), \u0003מה אלון מורה האמור להלן\u0004 באברהם הוא \u0003שכם —\u0004 \u0003אף כאן\u0004 אלוני מורה הוא \u0003שכם.\u0004","\u0003תניא\u0004 [\u0005שנויה\u0006 ברייתא], \u0003אמר ר' אלעזר בר' יוסי: בדבר זה זייפתי\u0004 (הוכחתי את זיופם) של \u0003ספרי כותיים. אמרתי להם: זייפתם תורתכם\u0004 והוספתם בה דברים, \u0003ולא העליתם בידכם כלום. שאתם אומרים אלוני מורה\u0004 זוהי \u0003שכם —\u0004 \u0003אף אנו מודים שאלוני מורה\u0004 זוהי \u0003שכם.\u0004 אולם \u0003אנו למדנוה בגזרה שוה, אתם\u0004 שאינכם לומדים גזירה שווה \u0003במה למדתום?\u0004","ואילו \u0003ר' אלעזר\u0004 חלק על דברי ר' יהודה ו\u0003אמר: \"הלא המה בעבר הירדן\"\u0004 — כוונתו \u0003סמוך לירדן, דאי\u0004 \u0005[שאם]\u0006 \u0003מעבר הירדן ואילך\u0004 רחוק משם, \u0003הלא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"והיה בעברכם את הירדן\u0004 תקימו את האבנים האלה... בהר עיבל\u0003\"\u0004 (דברים כז, ד), משמע — סמוך למקום המעבר.","\u0003\"אחרי דרך מבוא השמש\"\u0004 — כוונתו לשיטת ר' אלעזר \u0003מקום שהחמה שוקעת,\u0004 במערב. ליד שכם במרכז הארץ, ועוד, הרי נאמר \u0003\"בארץ הכנעני\",\u0004 והלא איזור שכם \u0003ארץ חוי היא\u0004 (כמבואר בבראשית לד, ב)!","וכן איך אפשר לתאר עם זה בכינוי \u0003\"הישב בערבה\" —\u0004 \u0003והלא בין הרים וגבעות הן יושבין! \"מול הגלגל\" —\u0004 \u0003והלא לא ראו את הגלגל\u0004 שהוא רחוק משכם! אלא לדעתו הר גריזים והר עיבל אינם אלו הידועים לנו שהם באיזור שכם, אלא הם במקום אחר, סמוך לירדן.","\u0003ר' אליעזר בן יעקב אומר: לא בא הכתוב\u0004 לקבוע את מקומם של הר גריזים והר עיבל \u0003אלא להראות להן דרך בשניה\u0004 בלכתם בארץ כנען \u0003כדרך שהראה להן בראשונה\u0004 בצאתם ממצרים, שהיה עמוד הענן הולך לפניהם והופך את הדרך לנוחה להליכה. ולכן נאמר פסוק זה להורות להם כיצד ילכו בארץ כנען. \u0003\"דרך\"\u0004 כוונתו — \u0003בדרך לכו, ולא בשדות וכרמים. \"הישב\" —\u0004 \u0003בישוב לכו, ולא במדברות. \"בערבה\" —\u0004 \u0003בערבה\u0004 במקום מישור \u0003לכו, ולא בהרים וגבעות.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד עברו ישראל את הירדן? בכל יום\u0004 היה ה\u0003ארון,\u0004 ארון הברית, \u0003נוסע אחר שני דגלים\u0004 שדגל מחנה יהודה ומחנה ראובן נוסעים ראשונה, \u0003והיום נסע\u0004 הארון \u0003תחילה, שנאמר:\u0004 \u0003\"הנה ארון הברית אדון כל הארץ עבר לפניכם\"\u0004 (יהושע ג, יא). \u0003בכל יום ויום לוים נושאין את הארון והיום נשאוהו כהנים, שנאמר: \"והיה כנוח כפות רגלי הכהנים נשאי ארון ה'\"\u0004 (יהושע ג, יג).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: בשלשה מקומות נשאו כהנים את הארון: כשעברו את הירדן\u0004 כנזכר, \u0003וכשהסיבו\u0004 (סובבו) \u0003את יריחו\u0004 (יהושע פרק ו), \u0003וכשהחזירוהו למקומו\u0004 בימי שלמה אל קדש הקדשים (מלכים א ח, ו)."],["\u0003וכיון שניטבלו רגלי כהנים במים\u0004 של הירדן \u0003חזרו המים לאחוריהם, שנאמר: \"וכבוא נשאי הארון עד הירדן... ויעמדו המים הירדים מלמעלה קמו נד אחד\"\u0004 (יהושע ג, טו-טז). \u0003וכמה גובהן של מים —\u0004 \u0003שנים עשר מיל על שנים עשר מיל, כנגד\u0004 גודלו של \u0003מחנה ישראל,\u0004 שעברו אז את הירדן. אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר לו ר' אלעזר בר' שמעון: לדבריך, אדם קל\u0004 (מהיר יותר) \u0003או מים קלים\u0004 (מהירים יותר)? \u0003הוי אומר —\u0004 \u0003מים קלים\u0004 יותר. \u0003אם כן\u0004 עד שמחנה ישראל עובר, \u0003באין מים ושוטפין אותן,\u0004 שהרי לאחר שהצטברו המים לגובה שנים עשר מיל חזרו לזרום!","\u0003אלא מלמד שהיו מים נגדשין ועולין כיפין\u0004 (כיפות) \u0003על גבי כיפין, יתר משלש מאות מיל, עד שראו אותן כל מלכי מזרח ומערב, שנאמר: \"ויהי כשמע כל מלכי האמרי אשר בעבר הירדן ימה וכל מלכי הכנעני אשר על הים את אשר הוביש ה' את מי הירדן מפני בני ישראל עד עברם וימס לבבם ולא היה בם עוד רוח מפני בני ישראל\"\u0004 (יהושע ה, א).","\u0003ואף רחב הזונה אמרה לשלוחי יהושע \"כי שמענו את אשר הוביש ה' את מי ים סוף\"\u0004 (יהושע ב, י), שעדיין היו מלאים אימה מן המעשה של קריעת ים סוף שהיה זמן רב קודם לכן ובמקום רחוק, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ונשמע וימס לבבנו ולא קמה עוד\u0004 רוח באיש מפניכם","\u0003\"\u0004(יהושע ה, יא). ומכאן מובן כמה פחדו כשהיה הדבר סמוך וקרוב להם. ב\u0003עודם בירדן אמר להם יהושע: דעו על מה אתם עוברים את הירדן —\u0004 \u0003על מנת שתורישו את יושבי הארץ מפניכם, שנאמר: \"והורשתם את כל ישבי הארץ מפניכם\"\u0004 (במדבר לג, נב). \u0003אם אתם עושין כן —\u0004 \u0003מוטב, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003באין מים ושוטפין אותיכם.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 הלשון \u0003\"אותיכם\"\u0004 — הרי היא צירוף המלים: \u0003אותי ואתכם.\u0004","\u0003עודם בירדן אמר להן יהושע: \"והרימו לכם איש אבן אחת על שכמו למספר שבטי בני ישראל\"\u0004 (יהושע ד, ה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"למען תהיה זאת אות בקרבכם כי ישאלון בניכם מחר לאמר מה האבנים האלה לכם\"\u0004 (יהושע ד, ו), הרי הן \u0003סימן לבנים שעברו אבות את הירדן.\u0004","\u0003עודם בירדן אמר להן יהושע: \"שאו לכם מזה מתוך הירדן ממצב רגלי הכהנים הכין שתים עשרה אבנים והעברתם אותם עמכם והנחתם אותם במלון אשר תלינו בו הלילה\"\u0004 (יהושע ד, ג). \u0003יכול בכל מלון ומלון\u0004 צריכים לשים את האבנים הללו — \u0003תלמוד לומר: \"אשר תלינו בו הלילה\",\u0004 רק בלילה זה.","\u0003א\u0004 \u0003אמר ר' יהודה: אבא חלפתא ור' אליעזר בן מתיא וחנניא בן חכינאי עמדו על אותן אבנים\u0004 שהוציאו ישראל מן הירדן, \u0003ושיערום\u0004 (והעריכו את גודלן) ש\u0003כל אחת ואחת שקולה כארבעים סאה. וגמירי דטעונא דמדלי איניש לכתפיה תילתא דטעוניה הוי\u0004 \u0005[ולמודים\u0006 אנו \u0005שמשא שמעלה אדם\u0006 בעצמו \u0005על כתפו\u0006 הוא \u0005שליש\u0006 של \u0005משאו]\u0006 שיכול לשאת כשאחרים מסייעים לו.","\u0003ומכאן אתה מחשב ל\u0004גודלו של ה\u0003אשכול\u0004 שנשאו המרגלים וסייעו זה לזה. \u0003שנאמר \"וישאהו במוט בשנים\"\u0004 (במדבר יג, כג), \u0003ממשמע שנאמר \"במוט\" איני יודע שבשנים?\u0004 שהרי נושאים במוט רק בשנים. \u0003מה\u0004 אם כן \u0003תלמוד לומר \"בשנים\" —\u0004 \u0003בשני מוטות,\u0004 שנשאוהו ארבעה אנשים, ומכאן שמשקלו של האשכול היה ארבע מאות ושמונים סאה.","\u0003אמר ר' יצחק: טורטני וטורטני דטורטני\u0004 (מאזניים ומאזניים למאזניים) כלומר, לא שני מוטות בלבד היו אלא ארבעה, \u0003הא כיצד? שמנה נשאו אשכל, אחד\u0004 מהם \u0003נשא רימון, ואחד נשא תאינה. יהושע וכלב לא נשאו כלום,\u0004 ומדוע? \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003משום דחשיבי\u0004 \u0005[ש\u0006היו \u0005חשובים]\u0006 מן האחרים ולא היה לפי כבודם לשאת משא. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ש\u0003לא\u0004 \u0003היו באותה עצה\u0004 רעה, שהרי המרגלים הביאו את האשכול רק כדי להפחיד בו את העם.","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 במחלוקת התנאים על גובהם של מי הירדן בשעת החציה \u0003ר' אמי ור' יצחק נפחא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לדברי ר' יהודה\u0004 שאמר שנים עשר מיל"],["\u0003כחנייתן עברו,\u0004 כלומר, כדרך שהיה המחנה מסודר בשעת חנייה כך עברו את הירדן, ולכן היה גובהם של המים רק שנים עשר מיל, עד כדי שיעבור המחנה. \u0003לדברי ר' אלעזר בר' שמעון\u0004 שאמר: יתר משלוש מאות מיל — \u0003בזה אחר זה\u0004 בשורה \u0003עברו\u0004 את הירדן, לכן נמשך הדבר זמן רב וגבהו המים כל כך.","\u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: בין מר\u0004 \u0005[\u0006ל\u0005חכם זה]\u0006 \u0003ובין מר\u0004 \u0005[\u0006ל\u0005חכם זה]\u0006 \u0003כ\u0004דרך \u0003חנייתן עברו.\u0004 אלא \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר: אדם קל\u0004 (מהיר) מן המים, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר בר' שמעון\u0005]\u0006 \u0003סבר: מים קלים\u0004 מן האדם.","כיון שהזכרנו את האשכול שהביאו המרגלים באים לדון בהם. על מה שנאמר שאמר ה' למשה לגבי המרגלים \u0003\"שלח לך אנשים\"\u0004 (במדבר יג, ב), \u0003אמר ריש לקיש: \"שלח לך\"\u0004 — כוונתו \u0003מדעתך\u0004 ולא כמצוותו של הקדוש ברוך הוא. שאם ה' הוא שאמר לשלוח את המרגלים, \u0003וכי אדם זה בורר חלק רע לעצמו?\u0004 שהרי ידע מה טיבם ושסופם להוציא דיבת הארץ. \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 על ידי משה בענין זה כי העם הוא אשר ביקש לשלוח את המרגלים, ומשביקש כן \u0003\"וייטב בעיני הדבר\"\u0004 (דברים א, כג). ו\u0003אמר ריש לקיש:\u0004 ההדגשה היא \u0003\"בעיני\" —\u0004 \u0003ולא בעיניו של מקום.\u0004","על מה שנאמר \u0003\"ויחפרו לנו את הארץ\"\u0004 (דברים א, כב), \u0003אמר ר' חייא בר אבא:\u0004 כאשר ביקשו בני ישראל לשלוח \u0003מרגלים, לא נתכוונו אלא לבושתה של ארץ ישראל.\u0004 וראיה לכך, \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויחפרו לנו את הארץ\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"וחפרה הלבנה ובושה החמה\"\u0004 (ישעיה כד, כג), משמע שחפירה — לשון בושה היא.","על מה שנאמר במרגלים \u0003\"ואלה שמותם למטה ראובן שמוע בן זכור\"\u0004 (במדבר יג, ד), \u0003אמר ר' יצחק: דבר זה מסורת בידינו מאבותינו: מרגלים על שם מעשיהם נקראו, ואנו לא עלתה בידינו אלא\u0004 פירושו של שם \u0003אחד: \"סתור בן מיכאל\"\u0004 (במדבר יג, יג), \u0003\"\u0004\u0003סתור\"\u0004 \u0003—\u0004 \u0003שסתר מעשיו של הקדוש ברוך הוא. \"מיכאל\" —\u0004 \u0003שעשה עצמו\u0004 (כביכול, את הקדוש ברוך הוא) \u0003מך\u0004 (נמוך).","\u0003אמר ר' יוחנן: אף אנו נאמר\u0004 דרשה בדבר: \u0003\"נחבי בן ופסי\"\u0004 (במדבר יג, יד), \u0003\"נחבי\" —\u0004 \u0003שהחביא דבריו\u0004 (גרם להסתירם, שלא אמר את הדברים כהווייתם) \u0003של הקדוש ברוך הוא. \"ופסי\" —\u0004 \u0003שפיסע\u0004 (דרך בזלזול) \u0003על מדותיו של הקדוש ברוך הוא.\u0004","על מה שנאמר עוד במרגלים \u0003\"ויעלו בנגב ויבא עד חברון\"\u0004 (במדבר יג, כב), מקשים: הלא \u0003\"ויבאו\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 ומדוע נאמר בלשון יחיד? \u0003אמר רבא: מלמד שפירש כלב מעצת מרגלים,\u0004 \u0003והלך ונשתטח על קברי אבות\u0004 שבחברון. \u0003אמר להן: אבותי! בקשו עלי רחמים שאנצל מעצת מרגלים.\u0004","ומעירים: ואילו \u0003יהושע\u0004 לא הלך לשם כי \u0003כבר בקש משה עליו רחמים, שנאמר:\u0004 \u0003\"ויקרא משה להושע בן נון יהושע\"\u0004 (במדבר יג, טז) שכוונתו: \u0003יה\u0004 (ה') \u0003יושיעך מעצת מרגלים. והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"ועבדי כלב עקב היתה רוח אחרת עמו\"\u0004 (במדבר יד, כד), לומר ששינה את דעתו במשך הזמן, ואילו יהושע מתחילה כך היה בדעתו.","על חברון מסופר באותה פרשה \u0003\"ושם אחימן ששי ותלמי\u0004 ילידי הענק\u0003\"\u0004 (במדבר יג, כב). ומבארים את פשר השמות: \u0003\"אחימן\"\u0004 נקרא כך מפני שהוא \u0003מיומן\u0004 (זריז ומוצלח) \u0003שבאחיו, \"ששי\" —\u0004 \u0003שמשים את הארץ כשחתות\u0004 (בורות) בהליכתו, מפני גודלו, \u0003\"תלמי\" —\u0004 \u0003שמשים את הארץ תלמים תלמים\u0004 בהליכתו, מפני כובדו.","\u0003דבר אחר: \"אחימן\" —\u0004 הוא זה ש\u0003בנה\u0004 את העיר \u0003ענת, \"ששי\"\u0004 — \u0003בנה\u0004 את \u0003אלש, \"תלמי\"\u0004 — \u0003בנה\u0004 את \u0003תלבוש. \"ילידי הענק\" —\u0004 \u0003שמעניקין חמה בקומתן,\u0004 שהם גבוהים כל כך שנראים כאילו החמה היא ענק לצווארם.","על מה שנאמר עוד \u0003\"וחברון שבע שנים נבנתה\u0004 לפני צוען מצרים\u0003\"\u0004 (במדבר יג, כב), שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נבנתה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003נבנתה ממש,\u0004 וכי \u0003אפשר אדם בונה בית לבנו קטן קודם\u0004 שבונה \u0003לבנו גדול?! דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובני חם כוש ומצרים\u0004 ופוט וכנען \u0003\"\u0004\u0003(בראשית י, ו) וכנען הלא היה הבן הקטן, וכיצד נבנתה עירו לפני עירו של מצרים?\u0004","\u0003אלא\u0004 הכוונה היא \u0003שהיתה מבונה\u0004 (פוריה יותר) \u0003על אחד משבעה\u0004 (פי שבע) \u0003בצוען. ואין לך\u0004 מקום שיש בו \u0003טרשים בכל ארץ ישראל יתר מחברון,\u0004 והראיה לדבר: \u0003משום דקברי\u0004 \u0005[שקוברים]\u0006 \u0003בה שיכבי\u0004 \u0005[מתים]\u0006 וזהו דבר הנעשה בקרקע שאינה ראויה לעיבוד, ולכן שם הוא מקום קבורת האבות. \u0003ואין לך מעולה בכל הארצות יתר מארץ מצרים, שנאמר:\u0004 \u0003\"כגן ה' כארץ מצרים\"\u0004 (בראשית יג, י), \u0003ואין לך מעולה בכל ארץ מצרים יתר מצוען,\u0004 וראיה לדבר, ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי היו בצען שריו\"\u0004 (של פרעה מלך מצרים) (ישעיה ל, ד) ובודאי במקום המובחר שבמדינה היו יושבים, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003חברון מבונה אחד משבעה בצוען.\u0004","ושואלים: \u0003וחברון\u0004 מקום \u0003טרשים הוי\u0004 \u0005[היא]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי מקץ ארבעים שנה ויאמר אבשלום אל המלך אלכה נא\u0004 ואשלם את נדרי אשר נדרתי לה' בחברון \u0003\"\u0004\u0003(שמואל ב טו, ז),\u0004 \u0003ואמר רב אויא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר בר חנן: שהלך\u0004 אבשלום \u0003להביא כבשים מחברון\u0004 דווקא. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 שמביאים למקדש קרבנות מן המובחר ביותר, \u0003אילים\u0004 מביאים \u0003ממואב, כבשים\u0004 מביאים \u0003מחברון,\u0004 משמע שהארץ בחברון היא טובה, שמגדלת כבשים שמנים! ומשיבים: \u0003מינה\u0004 \u0005[ממנה],\u0006 מתוך קושיה זו עצמה אנו מוצאים ראיה לדבר, שכן \u0003איידי דקלישא ארעא עבדה רעיא ושמן קניינא\u0004 \u0005[מתוך שקלושה\u0006 היא \u0005האדמה\u0006 ואינה עמוקה, הריהי \u0005מוציאה\u0006 רק עשב ל\u0005מרעה ומשמין המקנה].\u0006","נאמר במרגלים: \u0003\"וישבו מתור הארץ\u0004 מקץ ארבעים יום"],["\u0003וילכו ויבאו\"\u0004 (במדבר יג, כה-כו). \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מקיש\u0004 (משווה) הכתוב בזה \u0003הליכה לביאה, מה ביאה\u0004 כשחזרו — \u0003בעצה רעה, אף הליכה\u0004 שהלכו לשם — \u0003בעצה רעה\u0004 היתה.","נאמר שם \u0003\"ויספרו לו ויאמרו באנו\u0004 אל הארץ אשר שלחתנו וגם זבת חלב ודבש היא\u0003\"\u0004 (במדבר יג, כז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אפס כי עז העם\u0004 היושב בארץ\u0003\"\u0004 (במדבר יג, כח) ויש כאן איפוא סתירה בתכלית דבריהם. \u0003אמר ר' יוחנן (סימן אמ\"ת לבד\"ו לוי\"ה) משום\u0004 (בשם) \u0003ר' מאיר: כל לשון הרע שאין בו דבר אמת בתחילתו —\u0004 \u0003אין מתקיים\u0004 ואינו מתקבל על דעת הבריות \u0003בסופו.\u0004 ולכן תחילה דיברו קצת בשבחה של הארץ, ואחר כך דיברו בגנותה.","על מה שנאמר \u0003\"ויהס כלב את העם אל משה\"\u0004 (במדבר יג, ל), \u0003אמר רבה:\u0004 \"ויהס\" — \u0003שהסיתן בדברים.\u0004 כיצד היה הדבר?","— \u0003פתח יהושע\u0004 בדברים עם העם, \u0003דקא משתעי אמרי ליה\u0004 \u0005[כשהיה מדבר אמרו לו]:\u0006 \u0003דין ראש קטיעה\u0004 \u0005[זה הראש הקטוע]\u0006 שאין לו בנים, והוא ראש משפחה בלא משפחה \u0003ימלל\u0004 \u0005[ידבר]?\u0006 ומה לו לדבר על ארץ ישראל.","\u0003אמר\u0004 כלב בליבו: \u0003אי משתעינא\u0004 \u0005[אם אדבר] —\u0006 \u0003אמרי בי מילתא וחסמין לי\u0004 \u0005[יאמרו\u0006 גם \u0005עלי דבר ויחסמו אותי\u0006 מלדבר\u0005].\u0006 ולכן פתח ו\u0003אמר להן: וכי זו בלבד עשה לנו בן עמרם? סברי בגנותיה קא משתעי, אישתיקו\u0004 \u0005[סברו\u0006 ש\u0005בגנותו\u0006 של משה הוא רוצה \u0005לדבר\u0006 ו\u0005שתקו].\u0006","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הוציאנו ממצרים, וקרע לנו את הים, והאכילנו את המן. אם יאמר\u0004 לנו \u0003\"עשו סולמות ועלו לרקיע\" לא נשמע לו? \"עלה נעלה וירשנו אתה\"\u0004 (במדבר יג, ל), שאף לשמים נעלה אם יצווה עלינו.","על מה שנאמר שם \u0003\"והאנשים אשר עלו עמו אמרו לא נוכל\u0004 לעלות אל העם כי חזק הוא ממנו\u0003\"\u0004 (במדבר יג, לא), \u0003אמר ר' חנינא בר פפא: דבר גדול דברו מרגלים באותה שעה.\u0004 כלומר, מה שאמרו המרגלים הוא חמור יותר ממה שנשמע לכאורה, כי כאשר אמרו \u0003\"כי חזק הוא ממנו\"\u0004 (במדבר יג, לא) \u0003אל תקרי\u0004 \u0005[תקרא,\u0006 תאמר\u0005]\u0006 שמשמעות \u0003\"ממנו\"\u0004 היא מאיתנו, \u0003אלא ממנו\u0004 (מאיתו) — \u0003כביכול אפילו בעל הבית,\u0004 הקדוש ברוך הוא, \u0003אינו יכול להוציא כליו משם,\u0004 שהכנעני חזק יותר מן הקדוש ברוך הוא. משמע שדברי כפירה ממש דיברו.","על הפסוק \u0003\"ארץ אכלת יושביה היא\"\u0004 (במדבר יג, לב) \u0003דרש רבא, אמר הקדוש ברוך הוא: אני חשבתיה לטובה, והם חשבו לרעה. אני חשבתיה לטובה\u0004 שימותו שם אנשים רבים, ומדוע — ש\u0003כל היכא דמטו\u0004 \u0005[מקום שבאו]\u0006 אליו המרגלים, \u0003מת חשיבא דידהו\u0004 \u0005[החשוב שבהם,\u0006 בכנענים\u0005]\u0006 \u0003כי היכי דניטרדו\u0004 \u0005[כדי שיטרדו]\u0006 באבלם \u0003ולא לשאלו אבתרייהו\u0004 \u0005[ישאלו אחריהם]\u0006 מה מעשיהם. והם, המרגלים, פירשו זאת לרעה בחושבם שזהו טבעה של הארץ. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 מאת ה' היתה ש\u0003איוב נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 אז, \u0003ואטרידו כולי עלמא בהספידא\u0004 \u0005[והוטרדו הכל בהספד]\u0006 כדי שלא ישימו לב אליהם, ואילו \u0003הם חשבו\u0004 זאת \u0003לרעה,\u0004 שאמרו \u0003\"ארץ אכלת יושביה היא\".\u0004","על מה שנאמר \u0003\"ונהי בעינינו כחגבים וכן היינו\u0004 בעיניהם\u0003\"\u0004 (במדבר יג, לג), \u0003אמר רב משרשיא: מרגלים שקרי הוו\u0004 \u0005[שקרנים היו],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרו \u0003\"ונהי בעינינו כחגבים\" —\u0004 \u0003לחיי\u0004 \u0005[בסדר],\u0006 \u0003אלא\u0004 מה שהוסיפו ואמרו \u0003\"וכן היינו בעיניהם\", מנא הוו ידעי\u0004 \u0005[מניין היו יודעים]?\u0006","ומעירים: \u0003ולא היא,\u0004 אין הדבר כן, \u0003כי הוו מברי אבילי\u0004 \u0005[כאשר היו\u0006 הכנענים \u0005מברים,\u0006 עורכים סעודת הבראה ל\u0005אבלים] —\u0006 \u0003תותי ארזי הוו מברי\u0004 \u0005[תחת הארזים היו מברים\u0006 אותם\u0005],\u0006 \u0003וכי חזינהו, סלקו יתבי באילני\u0004 \u0005[וכאשר ראו אותם\u0006 המרגלים, \u0005עלו\u0006 ו\u0005ישבו באילנות],\u0006 \u0003שמעי דקאמרי\u0004 \u0005[\u0006והיו \u0005שומעים ש\u0006האנשים \u0005אומרים]:\u0006 \u0003קחזינן אינשי דדמו לקמצי באילני\u0004 \u0005[רואים אנו אנשים הדומים לחגבים באילנות].\u0006","על מה שנאמר \u0003\"ותשא כל העדה ויתנו את קולם ויבכו\"\u0004 (במדבר יד, א), \u0003אמר רבה אמר ר' יוחנן: אותו היום ערב תשעה באב היה, אמר הקדוש ברוך הוא: הן בכו\u0004 באותו יום \u0003בכיה של חנם —\u0004 \u0003ואני אקבע להם\u0004 בו ביום \u0003בכיה לדורות.\u0004","נאמר \u0003\"ויאמרו כל העדה לרגום אתם באבנים\"\u0004 (במדבר יד, י) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"וכבוד ה' נראה באהל מועד\"\u0004 (במדבר יד, י), \u0003אמר ר' חייא בר אבא: מלמד שנטלו אבנים וזרקום כלפי מעלה,\u0004 כביכול כלפי הקדוש ברוך הוא.","על מה שנאמר \u0003\"וימתו האנשים מוצאי דבת הארץ רעה במגפה\"\u0004 (במדבר יד, לז), \u0003אמר ר' שמעון בן לקיש: שמתו מיתה משונה\u0004 (\"רעה\"). \u0003אמר ר' חנינא בר פפא, דרש ר' שילא איש כפר תמרתא: מלמד שנשתרבב לשונם\u0004 מפיהם \u0003ונפל על טיבורם, והיו תולעים יוצאות מלשונם ונכנסות בטיבורם, ו\u0004יוצאות \u0003מטיבורם ונכנסות בלשונם,\u0004 וזו המיתה הרעה שמתו בה. \u0003ורב נחמן בר יצחק אמר: באסכרה מתו,\u0004 שהיא מיתה קשה של חנק.","וחוזרים לענין ביאת בני ישראל לארץ, \u0003וכיון שעלה האחרון שבישראל מן הירדן חזרו מים למקומן, שנאמר:\u0004 \u0003\"ויהי כעלות הכהנים נשאי ארון ברית ה' מתוך הירדן נתקו כפות רגלי הכהנים אל החרבה וישבו מי הירדן למקומם וילכו כתמול שלשום על כל גדותיו\"\u0004 (יהושע ד, יח),","\u0003נמצא ארון ונושאיו וכהנים מצד אחד\u0004 של הירדן, לצד מזרח, שחזרו אחורנית, \u0003וישראל מצד אחר\u0004 לצד מערב. \u0003נשא ארון את נושאיו\u0004 באויר \u0003ועבר, שנאמר:\u0004 \u0003\"ויהי כאשר תם כל העם לעבר ויעבר ארון ה' והכהנים לפני העם\"\u0004 (יהושע ד, יא).","\u0003ועל דבר זה\u0004 שלא שמר עליו \u0003נענש עוזא, שנאמר:\u0004 \u0003\"ויבאו עד גרן כידן וישלח עזא את ידו לאחז את הארון\u0004 כי שמטו הבקר\u0003\"\u0004 (דברי הימים א יג, ט). \u0003אמר לו הקדוש ברוך הוא\u0004 \u0003לעוזא:\u0004 \u0003עוזא,\u0004 הארון את \u0003נושאיו נשא,\u0004 כשעברו את הירדן, את \u0003עצמו לא כל שכן\u0004 שנושא!","נאמר \u0003\"ויחר אף ה' בעזה ויכהו שם\u0004 האלקים \u0003על השל\"\u0004 (שמואל ב ו, ז). \u0003ר' יוחנן ור' אלעזר\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם פירש ו\u0003אמר: על עסקי שלו\u0004 (שכחתו), על ששכח את הדבר הזה. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: שעשה צרכיו בפניו,\u0004 ומפרש \"של\" — שהרים את שולי בגדו בפני הארון.","על מה שנאמר \u0003\"וימת שם עם ארון האלהים\"\u0004 (שמואל ב ו, ז), \u0003אמר ר' יוחנן: עוזא בא לעולם הבא, שנאמר:\u0004 \u0003\"עם ארון האלהים\" —\u0004 \u0003מה ארון לעולם קיים —\u0004 \u0003אף עוזא בא לעולם הבא.\u0004","ועל מה שנאמר \u0003\"ויחר לדוד על אשר פרץ ה' פרץ בעזה\"\u0004 (שמואל ב ו, ח), \u0003אמר ר' אלעזר:\u0004 \"ויחר\" משמעו \u0003שנשתנו פניו כחררה\u0004 (פת אפויה), כלומר, הושחרו פניו מצער.","ותוהים: \u0003אלא מעתה כל היכא\u0004 \u0005[מקום]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויחר\"\u0004 ואף במקומות שנאמר \"ויחר אף ה'\" \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תפרש?! ומשיבים: \u0003התם כתיב\u0004 \u0005[שם,\u0006 באותם מקומות \u0005נאמר]\u0006 \u0003\"\u0004\u0003ויחר\u0004 \u0003אף\"\u0004 (שמואל ב ו, ז), ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אף\"\u0004 אלא רק \"ויחר\", ולכן דרשו דרשה זו.","\u0003דרש רבא: מפני מה נענש דוד\u0004 במיתת עוזה — \u0003מפני שקרא לדברי תורה \"זמירות\", שנאמר:\u0004 \u0003\"זמרות היו לי חקיך בבית מגורי\"\u0004 (תהלים קיט, נד).","\u0003אמר לו הקדוש ברוך הוא\u0004 \u0003: דברי תורה שכתוב בהן \"התעיף עיניך בו ואיננו\"\u0004 (משלי כג, ה), שהמסיר עיניו לרגע מן התורה שוכח אותה, שהיא חמורה וקשה כל כך, \u0003אתה קורא אותן \"זמירות\"?!\u0004 על כן \u0003הריני מכשילך בדבר שאפילו תינוקות של בית רבן יודעין אותו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולבני קהת לא נתן\u0004 (עגלות למשא) \u0003כי עבדת הקדש\u0004 עליהם בכתף ישאו\u0003\"\u0004 (במדבר ז, ט), הרי שאת הארון צריך לשאת בכתף, \u0003ואיהו אתייה בעגלתא\u0004 \u0005[והוא,\u0006 דוד, \u0005הביא אותו בעגלה]\u0006 שלא כדין.","נאמר כאשר החזירו הפלשתים את הארון בימי שמואל \u0003\"ויך באנשי בית שמש כי ראו בארון\u0004 ה'\" (שמואל א ו, יט) ותוהים: \u0003משום\u0004 ש\u0003ראו —\u0004 \u0003\"ויך\" (אלהים)\u0004 (שמואל א ו, יט), מדוע נענשו על כך? \u0003ר' אבהו ור' אלעזר\u0004 נחלקו בפירוש הדבר, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: קוצרין ומשתחוים היו,\u0004 שלא בטלו ממלאכתם, ומשום כך נענשו, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: מילי נמי אמור\u0004 \u0005[דברים\u0006 של גנות \u0005גם כן אמרו]:\u0006"],["\u0003מאן אמריך (להא) דאימריית ומאן אתא עלך דאיפייסת\u0004 \u0005[מי הרגיזך שכעסת\u0006 ונתת עצמך לשבי, \u0005ומי בא עליך שהתפייסת].\u0006","על מה שנאמר שם \u0003\"ויך בעם שבעים איש חמשים אלף איש\"\u0004 (שמואל א ו, יט), \u0003ר' אבהו ור' אלעזר\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: שבעים איש היו, וכל אחד ואחד\u0004 מהם \u0003שקול\u0004 היה \u0003כחמשים אלף\u0004 איש. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: חמשים אלף היו, וכל אחד ואחד\u0004 מהם \u0003שקול\u0004 היה \u0003כשבעים\u0004 איש שהיו ב\u0003סנהדרין.\u0004","נאמר כאשר העלה דוד את הארון לירושלים: \u0003\"ויהי כי צעדו נשאי ארון ה' ששה צעדים ויזבח שור ומריא\"\u0004 (שמואל ב ו, יג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר שזבח \u0003\"שבעה פרים ושבעה אילים\"\u0004 (דברי הימים א טו, כו). \u0003אמר רב פפא בר שמואל: על כל פסיעה ופסיעה\u0004 זבח \u0003שור ומריא, על כל שש ושש פסיעות —\u0004 \u0003שבעה פרים ושבעה אילים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: אם כן,\u0004 שעל כל פסיעה ופסיעה הקריבו קרבנות, \u0003מילאת את כל ארץ ישראל במות,\u0004 שהיו צריכים לבנות במה (מזבח) בכל פעם! \u0003אלא אמר רב חסדא: על כל שש ושש פסיעות —\u0004 \u0003שור ומריא, על כל ששה סדרים של שש פסיעות —\u0004 \u0003שבעה פרים ושבעה אילים.\u0004","\u0003כתיב\u0004 \u0005[כתוב]\u0006 במקום אחד על המקום שמת בו עוזה \u0003\"\u0004ויבואו עד גורן \u0003כידן\"\u0004 (דברי הימים א יג, ט), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר \u0003\"\u0004גורן \u0003נכון\"\u0004 (שמואל ב ו, ו). \u0003אמר ר' יוחנן: בתחלה\u0004 היה הארון כעין \u0003כידון,\u0004 שהוא כלי זין ההורג נפשות, שנהרג עוזה על ידו, \u0003ולבסוף,\u0004 לאחר שביקשו מחילה, היה \u0003נכון\u0004 (מבוסס, מיושב) בבית עובד אדום ובאה ברכה בגללו.","ושוב לענין הביאה לארץ \u0003נמצאת אתה אומר שלשה מיני אבנים היו: אחד שהקים משה בארץ מואב, שנאמר:\u0004 \u0003\"בעבר הירדן בארץ מואב הואיל משה באר\u0004 את התורה\u0003\"\u0004 (דברים א, ה), \u0003ולהלן\u0004 בציווי על הקמת האבנים בהר עיבל \u0003הוא אומר \"וכתבת עליהן את כל דברי התורה הזאת\u0004 באר היטב\u0003\"\u0004 (דברים כז, ח), \u0003ואתיא\u0004 \u0005[ובא,\u0006 נלמד\u0005]\u0006 בגזירה שווה \u0003\"באר\" \"באר\",\u0004 שגם משה כתב את דברי התורה על האבנים.","\u0003ואחד\u0004 \u0003שהקים יהושע בתוך הירדן, שנאמר: \"ושתים עשרה אבנים הקים יהושע בתוך הירדן\u0004... ויהיו שם עד היום הזה\" (יהושע ד, ט). \u0003ואחד שהקים\u0004 יהושע \u0003בגלגל, שנאמר: \"ואת שתים עשרה האבנים האלה אשר לקחו\u0004 מן הירדן הקים יהושע בגלגל \u0003\"\u0004\u0003(יהושע ד, כ).\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד כתבו ישראל את התורה? ר' יהודה אומר: על גבי אבנים כתבוה, שנאמר: \"וכתבת על האבנים\u0004 \u0003את כל דברי התורה הזאת\"\u0004 (דברים כז, ח) \u0003ואחר כך סדו אותן בסיד.\u0004","\u0003אמר לו ר' שמעון: לדבריך\u0004 שסדו בסיד על הכתב, \u0003היאך למדו אומות העולם תורה? אמר לו: בינה יתירה נתן בהם הקדוש ברוך הוא\u0004\u0003, ושיגרו נוטירין\u0004 (סופרים) \u0003שלהן, וקילפו את הסיד והשיאוה\u0004 (והעתיקו אותה). \u0003ועל דבר זה נתחתם גזר דינם לבאר שחת, ש\u0004כיון שהיתה התורה בידיהם \u0003היה להן ללמד ולא למדו.\u0004","\u0003ר' שמעון אומר:\u0004 לא כך היה, אלא \u0003על גבי סיד כתבוה, וכתבו להן למטה\u0004 \"למען אשר לא \u0003ילמדו אתכם לעשות ככל\u0004 תועבותם\u0003\"\u0004 (דברים כ, יח). \u0003הא למדת\u0004 \u0005[הרי אתה לומד]\u0006 מכך שכתבו פסוק זה \u0003שאם\u0004 היו הגוים שבארץ ישראל \u0003חוזרין בתשובה\u0004 — היו \u0003מקבלין אותן.\u0004","\u0003אמר רבא בר שילא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון —\u0004 \u0003דכתיב\u0004 \u0005[\u0006משום \u0005שנאמר]:\u0006 \u0003\"והיו עמים משרפות שיד\"\u0004 (ישעיה לג, יב) — \u0003על עסקי סיד,\u0004 שנענשו על שלא למדו את התורה שנכתבה על גבי הסיד.","\u0003ור' יהודה\u0004 מפרש: \u0003כי\u0004 \u0005[כמו]\u0006 \u0003סיד, מה סיד אין לו תקנה אלא שריפה —\u0004 \u0003אף אומות העולם אין להם תקנה אלא שריפה.\u0004","\u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו ששנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"\u0004כי תצא למלחמה על אויביך... \u0003ושבית שביו\"\u0004 (דברים כא, י), שאין אתה מצווה להשמידו — \u0003לרבות כנענים שבחוצה לארץ, שאם חוזרין בתשובה —\u0004 \u0003מקבלין אותן?\u0004"],["\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 \u0003כר' שמעון\u0004 שלדעתו הגוים שמחוץ לגבולות הארץ אינם בכלל \"לא תחיה כל נשמה\" (דברים כ, טז). שהרי אין בהם חשש \"למען אשר לא ילמדו אתכם לעשות ככל תועבותם\" (דברים כ, יח).","ושוב להמשך הדברים בענין הכניסה לארץ, \u0003בא וראה כמה נסים נעשו באותו היום: עברו ישראל את הירדן, ובאו להר גריזים ולהר עיבל,\u0004 שהוא מרחק \u0003יתר מששים מיל, ואין כל בריה יכולה לעמוד בפניהם\u0004 באותו יום, \u0003וכל העומד בפניהם מיד נתרז\u0004 (לוקה בשלשול), \u0003שנאמר:\u0004 \u0003\"את אימתי אשלח לפניך והמתי את כל העם אשר תבא בהם וגו'\"\u0004 (שמות כג, כז).","\u0003ו\u0004כן הוא \u0003אומר \"תפל עליהם אימתה ופחד... עד יעבר עמך ה'\"\u0004 (שמות טו, טז) — \u0003זו ביאה ראשונה\u0004 לארץ ישראל שבאו בזמן יהושע, \u0003\"עד יעבר עם זו קנית\"\u0004 (שמות טו, טז) — \u0003זו ביאה שניה\u0004 כשבאו מבבל אחרי חורבן בית ראשון.","\u0003אמור מעתה: ראויין היו ישראל לעשות להם נס בביאה שניה כביאה ראשונה, אלא שגרם החטא\u0004 ועלו כדרך הטבע וברשות מלכי האומות.","\u0003ואחר כך הביאו את האבנים, ובנו את המזבח\u0004 בהר עיבל, \u0003וסדוהו בסיד, וכתבו עליהם את כל דברי התורה בשבעים לשון, שנאמר:\u0004 \u0003\"\u0004וכתבת על האבנים את כל דברי התורה הזאת \u0003באר היטב\"\u0004 (דברים כז, ח),","\u0003והעלו עולות ושלמים, ואכלו ושתו ושמחו, וברכו\u0004 את הברכות \u0003וקללו\u0004 את הקללות האמורות, \u0003וקיפלו\u0004 והרימו \u0003את האבנים\u0004 ולקחו אותם, \u0003ובאו ולנו בגלגל, שנאמר:\u0004 \u0003\"והעברתם אותם עמכם והנחתם אותם במלון\"\u0004 (יהושע ד, ג).","\u0003יכול בכל מלון ומלון\u0004 צריכים לשים אותם — \u0003תלמוד לומר: \"אשר תלינו בו הלילה\"\u0004 (יהושע ד, ג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ואת שתים עשרה האבנים האלה אשר לקחו\u0004 מן הירדן הקים יהושע בגלגל\u0003\"\u0004 (יהושע ד, כ).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003צרעה לא עברה עמהם\u0004 מעבר הירדן. ושואלים: \u0003ולא? והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ושלחתי את הצרעה לפניך\u0004 וגרשה את החוי את הכנעני...\u0003\"\u0004(שמות כג, כח)!","\u0003אמר ר' שמעון בן לקיש: על שפת ירדן עמדה, וזרקה בהן מרה\u0004 (ארס). \u0003וסימתה עיניהן מלמעלה, וסירסתן מלמטה, שנאמר:\u0004 \u0003\"ואנכי השמדתי את האמרי מפניהם אשר כגבה ארזים גבהו וחסן הוא כאלונים ואשמיד פריו ממעל ושרשיו מתחת\"\u0004 (עמוס ב, ט).","\u0003רב פפא אמר: שתי צרעות הואי\u0004 \u0005[היו],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 זו של \u0003משה\u0004 כשכבשו את עבר הירדן המזרחי \u0003וחדא\u0004 \u0005[ואחת]\u0006 של \u0003יהושע,\u0004 זו של \u0003משה לא עבר\u0004 (עברה) את הירדן, ואילו זו של \u0003יהושע עבר\u0004.","שנינו במשנה: \u0003ששה שבטים עלו לראש הר גריזים.\u0004 נאמר \"חציו אל מול הר גריזים והחציו אל מול הר עיבל\" (יהושע ח, לג), ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"והחציו\"\u0004 המורה על חצי הידוע כבר? \u0003אמר רב כהנא: כדרך שחלוקין כאן\u0004 השבטים — \u0003כך\u0004 היו \u0003חלוקין באבני אפוד.\u0004 כלומר, אותו חצי העם כפי שכבר נחלק באבני האפוד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003שתי אבנים טובות היו לו לכהן גדול על כתיפיו, אחת מכאן ואחת מכאן, ושמות שנים עשר שבטים כתוב עליהם, ששה על אבן זו וששה על אבן זו, שנאמר:\u0004 \u0003\"ששה משמתם על האבן האחת\u0004 ואת שמות הששה הנותרים על האבן השנית כתולדותם\u0003\"\u0004(שמות כח, י),","ומדוייק מכאן שדווקא אבן \u0003שניה\u0004 כתובה \u0003כתולדותם\u0004 לפי סדר לידתם: גד, אשר, יששכר, זבולון, יוסף ובנימין, \u0003ולא\u0004 היתה כתובה ה\u0003ראשונה כתולדותם, מפני שיהודה מוקדם\u0004 באבן הראשונה, ואחריו: ראובן, שמעון, לוי, דן ונפתלי. \u0003וחמשים אותיות היו\u0004 בשתי אבני האפוד, \u0003עשרים וחמש על אבן זו ועשרים וחמש על אבן זו.\u0004","\u0003ר' חנינא בן גמליאל אומר:\u0004"],["\u0003לא כדרך שחלוקין\u0004 השבטים \u0003ב\u0004סדר האמור בתחילת \u0003חומש הפקודים\u0004 (ספר \"במדבר\") (א, א-טו) \u0003חלוקין באבני אפוד, אלא כדרך שחלוקין בחומש שני\u0004 (ספר שמות) (א, ב-ד).","\u0003כיצד?\u0004 באבן אחת נמצאים \u0003בני לאה כסידרן:\u0004 ראובן, שמעון, לוי, יהודה, יששכר וזבולון. באבן השניה \u0003בני רחל אחד\u0004 בנימין \u0003מכאן\u0004 בשורה התחתונה \u0003ואחד\u0004 יוסף \u0003מכאן\u0004 בשורה העליונה, \u0003ובני שפחות\u0004 דן, נפתלי, גד ואשר \u0003באמצע.\u0004","\u0003ואלא\u0004 אם הסדר על האבנים לא היה כפי סדר לידתם \u0003מאי\u0004 \u0005[מה]\u0006 איך \u0003אני מקיים \"כתולדותם\"\u0004 — הכוונה \u0003כשמותן שקרא להן אביהן\u0004 מולידם, \u0003ולא כשמות\u0004 באופן \u0003שקרא להן משה.\u0004 שכך היה כתוב שם: \u0003\"ראובן\", ולא \"ראובני\", \"שמעון\", ולא \"שמעוני\", \"דן\" ולא \"הדני\", \"גד\" ולא \"הגדי\".\u0004 ואם כן הרי זה \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב כהנא\u0004 שהרי לאף אחת מן הדעות לא היה סדר השבטים באבני האפוד כסדרם בהר גריזים והר עיבל! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דבריו.","ושואלים: לדעת רב כהנא \u0003ואלא מאי\u0004 \u0005[מה\u0006 ההדגשה\u0005]\u0006 \u0003\"והחציו\u0004 אל מול הר עיבל\u0003\"\u0004 (יהושע ח, לג)? \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 שהכוונה היא להדגיש בה\"א הידיעה — החצי הקטן יותר הוא על הר עיבל, שכן \u0003חציו של מול הר גריזים מרובה מחציו של הר עיבל, מפני ש\u0004שבט \u0003לוי\u0004 שנכלל באלו של מול הר גריזים נמצא חלק ממנו \u0003למטה,\u0004 בין שני ההרים.","ותוהים: \u0003אדרבה\u0004 (להיפך), \u0003מפני שלוי למטה בצרי להו\u0004 \u0005[פחתו להם]!\u0006 ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף על פי שלוי\u0004 היה \u0003למטה —\u0004 \u0003בני יוסף\u0004 היו \u0003עמהם.\u0004 והם היו רבים, \u0003שנאמר: \"וידברו בני יוסף את יהושע לאמר מדוע נתתה לי נחלה גורל אחד וחבל אחד ואני עם רב... ויאמר אליהם יהושע אם עם רב אתה עלה לך היערה\"\u0004 (יהושע יז, יד-טו),","\u0003אמר להן: לכו והחבאו עצמכם ביערים, שלא תשלוט בכם עין הרע\u0004 על שאתם רבים כל כך. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני יוסף ליהושע: \u0003זרעיה\u0004 \u0005[זרעו]\u0006 של \u0003יוסף לא שלטא ביה עינא בישא\u0004 \u0005[שולטת בו עין הרע],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בן פרת יוסף בן פרת עלי עין\"\u0004 (בראשית מט, כב), \u0003ואמר ר' אבהו: אל תהי קורא \"עלי עין\" אלא \"עולי עין\",\u0004 לומר שהם מתעלים על עין הרע.","\u0003ר' יוסי בר' חנינא אמר: מהכא\u0004 \u0005[מכאן]\u0006 אנחנו למדים דבר זה, שנאמר בברכת יעקב לבני יוסף: \u0003\"וידגו לרב בקרב הארץ\"\u0004 (בראשית מח, טז), \u0003מה דגים שבים —\u0004 \u0003מים מכסין עליהן ואין העין שולטת בהן, אף זרעו של יוסף —\u0004 \u0003אין העין שולטת בהן.\u0004","ושואלים על הברייתא שהקשינו ממנה על רב כהנא: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003חמשים אותיות\u0004 הן בשמות השבטים שעל האפוד? הלא לפי מניין \u0003חמשים נכי חדא הויין\u0004 \u0005[פחות אחת הן]!\u0006 \u0003אמר ר' יצחק: יוסף הוסיפו לו אות אחת\u0004 בכתיבה על אבני האפוד, \u0003שנאמר: \"עדות ביהוסף שמו בצאתו על ארץ מצרים\"\u0004 (תהלים פא, ו).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק: \"כתולדותם\" בעינן\u0004 \u0005[צריכים אנו],\u0006 והוא לא נקרא בלידתו יהוסף! \u0003אלא,\u0004 יש לתרץ באופן אחר: ב\u0003כל התורה כולה \"בנימן\" כתיב\u0004 \u0005[נאמר]\u0006 חסר, \u0003והכא\u0004 \u0005[וכאן]\u0006 כשנולד כתוב \u0003\"בנימין\" שלם, כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"ואביו קרא לו בנימין\"\u0004 (בראשית לה, יח) מלא. וכתולדתו, כמו שקרא לו אביו בלידתו — כך נכתב שמו באפוד.","\u0003אמר רב חנא בר ביזנא אמר ר' שמעון חסידא: יוסף שקידש שם שמים בסתר,\u0004 שלא חטא בסתר עם אשת פוטיפר — \u0003הוסיפו עליו אות אחת משמו של הקדוש ברוך הוא\u0004\u0003, יהודה שקידש שם שמים בפרהסיא\u0004 על ים סוף כשיצאו ממצרים — \u0003נקרא כולו על שמו של הקדוש ברוך הוא\u0004 שהרי כל השם בן ארבע אותיות כלול בתוך השם יהודה.","ומפרשים: \u0003יוסף מאי היא\u0004 \u0005[מה היה]\u0006 עניינו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויהי כהיום הזה ויבא הביתה לעשות מלאכתו\"\u0004 (בראשית לט, יא) \u0003אמר ר' יוחנן: מלמד ששניהם\u0004 גם יוסף וגם אשת פוטיפר \u0003לדבר עבירה נתכוונו\u0004 ולשם כך בא הביתה. ועל אותו כתוב \u0003\"ויבא הביתה לעשות מלאכתו\"\u0004 גם נחלקו \u0003רב ושמואל; חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: לעשות מלאכתו ממש\u0004 כפשוטה, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: לעשות צרכיו\u0004 בתשמיש עימה \u0003נכנס.\u0004","נאמר \u0003\"ואין איש מאנשי הבית\u0004 שם בבית\u0003\"\u0004 (בראשית לט, יא) ותוהים:\u0003אפשר בית גדול\u0004 וחשוב \u0003כביתו של אותו רשע לא היה בו איש\u0004 ממשרתיו?! \u0003תנא דבי\u0004 \u0005[שנה החכם בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אותו היום יום חגם היה, והלכו כולן לבית עבודה זרה שלהם,\u0004 \u0003והיא אמרה להן חולה היא\u0004 ואינה יכולה ללכת, \u0003אמרה\u0004 בליבה: \u0003אין לי יום שנזקק לי יוסף כיום הזה.\u0004","נאמר \u0003\"ותתפשהו בבגדו לאמר\u0004 שכבה עמי\" (בראשית \u0003לט, יב).\u0004 \u0003באותה שעה באתה דיוקנו\u0004 (דמותו) \u0003של אביו ונראתה לו בחלון, אמר לו: יוסף! עתידין אחיך שיכתבו על אבני אפוד ואתה\u0004 צריך להיות \u0003ביניהם, רצונך שימחה שמך מביניהם, ותקרא רועה זונות? דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ורעה זונות יאבד הון\"\u0004 (משלי כט, ג), שיאבד על ידי כך כבוד זה הגדול מכל הון.","\u0003מיד —\u0004 \u0003\"ותשב באיתן קשתו\"\u0004 (בראשית מט, כד), \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' מאיר: ששבה קשתו\u0004 (שהוא כינוי לאיבר) \u0003לאיתנו,\u0004 שבטל ממנו יצרו. נאמר שם על יוסף \u0003\"ויפזו זרעי ידיו\"\u0004 (בראשית מט, כד) — \u0003נעץ ידיו בקרקע ויצאה שכבת זרעו מבין ציפורני ידיו.\u0004","\u0003\"מידי אביר יעקב\"\u0004 (בראשית מט, כד), \u0003מי גרם לו שיחקק על אבני אפוד —\u0004 \u0003אלא אביר יעקב. \"משם רעה אבן ישראל\"\u0004 (בראשית מט, כד), \u0003משם,\u0004 מתוך שעמד בנסיון \u0003זכה ונעשה רועה\u0004 לישראל, \u0003שנאמר:\u0004 \u0003\"רעה ישראל האזינה נהג כצאן יוסף\"\u0004 (תהלים פ, ב).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה ראוי יוסף לצאת ממנו שנים עשר שבטים כדרך שיצאו מיעקב אביו, שנאמר:\u0004 \u0003\"אלה תלדות יעקב יוסף\"\u0004 \u0005(בראשית לז, ב)\u0006 לומר שכל מה שאירע לזה אירע לזה, \u0003אלא שיצא שכבת זרעו מבין ציפורני ידיו. ואף על פי כן יצאו\u0004 תולדות הראוים לו \u0003מבנימין אחיו,\u0004 שהוליד עשרה בנים, \u0003וכולן נקראו על שמו\u0004 של יוסף, כלומר, ששמותיהם מתייחסים כולם ליוסף, \u0003שנאמר \"ובני בנימין בלע ובכר ואשבל\u0004 גרא ונעמן אחי וראש מופים וחופים וארד","\u0003\"\u0004(בראשית מו, כא), ופירושם: \u0003\"בלע\"\u0004 — על שם יוסף \u0003שנבלע בין האומות, \"ובכר\" —\u0004 \u0003בכור לאמו\u0004 רחל \u0003היה, \"ואשבל\" —\u0004 \u0003ששבאו אל\u0004 למצרים, \"\u0003גרא\" —\u0004 \u0003שגר באכסניות\u0004 בנכר,","\u0003\"ונעמן\" —\u0004 \u0003שנעים ביותר, \"אחי וראש\" —\u0004 \u0003אחי הוא וראשי הוא, \"מפים וחפים\"\u0004 — כוונתו: \u0003הוא לא ראה בחופתי, ואני לא ראיתי בחופתו, \"וארד\" —\u0004 \u0003שירד לבין אומות העולם. איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \"\u0003וארד\" —\u0004 \u0003שפניו דומין\u0004 ביופים \u0003לוורד.\u0004","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: בשעה שאמר לו פרעה ליוסף \"ובלעדיך לא ירים איש את ידו\u0004 ואת רגלו בכל ארץ מצרים\u0003\"\u0004 (בראשית מא, מד), \u0003אמרו איצטגניני פרעה: עבד שלקחו\u0004 (קנאו) \u0003רבו בעשרים כסף תמשילהו עלינו? אמר להן: גנוני\u0004 (מנהגי) \u0003מלכות אני רואה בו,\u0004 שאינו עבד מעיקרו.","\u0003אמרו לו: אם כן,\u0004 שבן מלכים הוא, \u0003יהא יודע בשבעים לשון\u0004 כדרך שלומדים בני המלכים! \u0003בא\u0004 המלאך \u0003גבריאל ולימדו שבעים לשון. לא הוה קגמר\u0004 \u0005[היה לומד]\u0006 כל זה. באותה שעה \u0003הוסיף לו\u0004 גבריאל \u0003אות אחת משמו של הקדוש ברוך הוא\u0004 \u0003ו\u0004אז \u0003למד, שנאמר:\u0004 \u0003\"עדות ביהוסף שמו בצאתו על ארץ מצרים שפת לא ידעתי אשמע\"\u0004 (תהלים פא, ו). \u0003ולמחר\u0004 כשחזר לפני פרעה, \u0003כל לישנא דאישתעי\u0004 \u0005[לשון,\u0006 שפה, שדיבר\u0005]\u0006 \u0003פרעה בהדיה\u0004 \u0005[איתו],\u0006 \u0003אהדר ליה\u0004 \u0005[ענה לו].\u0006","\u0003אישתעי איהו\u0004 \u0005[דיבר הוא,\u0006 יוסף\u0005]\u0006 \u0003בלשון הקדש\u0004 ו\u0003לא הוה קא ידע מאי הוה אמר\u0004 \u0005[היה יודע\u0006 פרעה \u0005מה הוא אומר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 פרעה: \u0003אגמרי\u0004 \u0005[למד אותי].\u0006 \u0003אגמריה\u0004 \u0005[לימד אותו]\u0006 \u0003ולא גמר\u0004 \u0005[למד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 פרעה: \u0003אישתבע\u0004 \u0005[השבע]\u0006 \u0003לי דלא מגלית\u0004 \u0005[שאינך מגלה]\u0006 שאיני יודע שפה זו. \u0003אישתבע\u0004 \u0005[נשבע]\u0006 \u0003לו.\u0004","לאחר זמן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 יוסף לפרעה \u0003\"אבי השביעני לאמר\"\u0004 (בראשית נ, ה) שאקברהו בארץ ישראל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 פרעה: \u0003זיל איתשיל אשבועתך\u0004 \u0005[לך הישאל על שבועתך]\u0006 והתר אותה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 יוסף: \u0003ואיתשלי נמי אדידך\u0004 \u0005[ואשאל גם כן\u0006 על השבועה \u0005ש\u0006נשבעתי \u0005לך]?\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא ניחא ליה\u0004 \u0005[\u0006היה \u0005נוח לו]\u0006 לפרעה להסכים, מפני שחשש שיוסף יישאל על השבועה שנשבע לו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 בכל זאת: \u0003\"עלה וקבר את אביך כאשר השביעך\"\u0004 (בראשית נ, ו).","\u0003יהודה מאי היא\u0004 \u0005[מה היה]\u0006 ענין קידוש השם שעשה בפרהסיא? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: כשעמדו ישראל על הים\u0004 (סוף) \u0003היו\u0004 ה\u0003שבטים מנצחים\u0004 (מתווכחים) \u0003זה עם זה, זה אומר: אני יורד תחלה לים, וזה אומר: אני יורד תחלה לים,\u0004 ובינתיים \u0003קפץ\u0004"],["\u0003שבטו של בנימין וירד לים תחילה, שנאמר: \"שם בנימן צעיר רדם\"\u0004 (תהלים סח, כח) \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"רדם\" אלא \"רד ים\". והיו שרי יהודה רוגמים אותם\u0004 על שקפצו תחילה שלא לפי הסדר, \u0003שנאמר: \"שרי יהודה רגמתם\"\u0004 (תהלים סח, כח).","\u0003לפיכך זכה בנימין הצדיק ונעשה אושפיזכן\u0004 (בעל אכסניה) \u0003לגבורה\u0004 (השכינה), שנבנה בית המקדש בחלקו, \u0003שנאמר\u0004 בברכת משה לשבט בנימין: \u0003\"\u0004ידיד ה'... \u0003ובין כתפיו שכן\"\u0004 (דברים לג, יב).","\u0003אמר לו ר' יהודה\u0004 לר' מאיר: \u0003לא כך היה מעשה, אלא\u0004 שבט \u0003זה אומר: אין אני יורד תחילה לים, ו\u0004שבט \u0003זה אומר: אין אני יורד תחילה לים, קפץ נחשון בן עמינדב\u0004 (נשיא שבט יהודה) \u0003וירד לים תחילה,\u0004 ושבט יהודה עימו \u0003שנאמר: \"סבבני בכחש אפרים ובמרמה בית ישראל ויהודה עד רד עם אל\"\u0004 (הושע יב, א).","\u0003ועליו,\u0004 על מעשה זה, \u0003מפרש בקבלה\u0004 (בספרי הכתובים), שכך התפלל באותה שעה: \u0003\"הושיעני אלהים כי באו מים עד נפש. טבעתי ביון מצולה ואין מעמד\" וגו'\u0004 (תהלים סט, ב-ג), וכן \u0003\"אל תשטפני שבלת מים ואל תבלעני מצולה\" וגו'\u0004 (תהלים סט, טז).","\u0003באותה שעה היה משה מאריך בתפלה, אמר לו הקדוש ברוך הוא: ידידיי טובעים בים ואתה מאריך בתפלה לפני?! אמר לפניו: רבונו של עולם! ומה בידי לעשות? אמר לו: \"דבר אל בני ישראל ויסעו. ואתה הרם את מטך ונטה את ידך\" וגו'\u0004 (שמות יד, טו-טז).","\u0003לפיכך\u0004 משום שקפץ לים, \u0003זכה\u0004 שבט \u0003יהודה לעשות\u0004 (להיעשות) \u0003ממשלה בישראל, שנאמר: \"היתה יהודה לקדשו ישראל ממשלותיו\"\u0004 (תהלים קיד, ב); \u0003מה טעם היתה יהודה לקדשו וישראל ממשלותיו\u0004 (תחת ממשלתו) — \u0003משום\u0004 ש\u0003\"הים ראה וינס\"\u0004 (תהלים קיד, ג).","ושוב לענין הברכות והקללות. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: אי אפשר לומר\u0004 שהיה שבט \u0003לוי למטה\u0004 בין שני ההרים, \u0003שכבר נאמר\u0004 שהוא \u0003למעלה,\u0004 כאמור \"אלה יעמדו לברך את העם על הר גריזים... שמעון ולוי ויהודה...\" (דברים כז, יב), \u0003ואי אפשר לומר\u0004 שהיה \u0003למעלה, שכבר נאמר\u0004 \"וכל ישראל וזקניו ושוטרים ושופטיו עומדים מזה ומזה לארון נגד הכהנים הלויים\" (יהושע ח, לג), משמע שהלויים היו \u0003למטה\u0004 עם הארון.","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — רק \u0003זקני כהונה ולויה\u0004 נמצאים \u0003למטה, והשאר למעלה. ר' יאשיה אומר:\u0004 \u0003כל\u0004 לוי \u0003הראוי לשרת\u0004 במקדש נמצא \u0003למטה, והשאר\u0004 הצעירים והזקנים מגיל העבודה במקדש היו \u0003למעלה.\u0004","\u0003רבי אומר: אלו ואלו\u0004 הלויים וכל שבטי ישראל \u0003למטה הן עומדים, הפכו פניהם כלפי הר גריזים ופתחו בברכה, כלפי הר עיבל ופתחו בקללה.\u0004 אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"אלה יעמדו לברך את העם \u0003על\u0004 הר גריזים\" (דברים כז, יב) האמור בתורה \u0003על —\u0004 \u0003בסמוך,\u0004 כלומר, סמוך להר ולא עליו ממש.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין לחם הפנים: על מה שנאמר \u0003\"ונתת על המערכת לבנה זכה\"\u0004 (ויקרא כד, ז) \u0003רבי אומר: \"על\"\u0004 כוונתו \u0003בסמוך. אתה אומר \"על\" בסמוך, או אינו אלא על ממש? כשהוא אומר \"וסכת על הארן\u0004 את הפרוכת\u0003\"\u0004 (שמות מ, ג) והרי הפרוכת לא היתה כיסוי לארון מלמעלה אלא רק סמוך לו, \u0003הוי אומר\u0004 ש\u0003\"על\"\u0004 פירושו \u0003בסמוך.\u0004","על מה ששנו במשנה: \u0003הפכו פניהם כלפי הר גריזים ופתחו בברכה כו', תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בברכות ובקללות יש \u0003\"ברוך\" בכלל\u0004 על המקיים את דברי התורה כולם, ו\u0003\"ברוך\" בפרט,\u0004 על כל אחד מן הדברים המפורטים בפרשת הברכות והקללות. וכן \u0003\"ארור\" בכלל\u0004 למי שלא יקיים את כל דברי התורה, ו\u0003\"ארור\" בפרט,\u0004 ובכל אחת מהברכות והקללות יש \u0003ללמוד וללמד לשמור ולעשות, הרי\u0004"],["\u0003ארבע,\u0004 מצוות נפרדות לכל מצוה ומצוה, \u0003ארבע וארבע\u0004 שבכלל שבפרט \u0003הרי שמונה, שמונה ושמונה\u0004 של \"ברוך\" ושל \"ארור\" \u0003הרי שש עשרה. וכן בסיני, וכן בערבות מואב שנאמר: \"אלה דברי הברית אשר צוה ה' את משה...\u0004 בארץ מואב מלבד הברית אשר כרת איתם בחורב\u0003\"\u0004 (דברים כח, סט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ושמרתם את דברי הברית הזאת\" וגו'\u0004 (דברים כט, ח). \u0003נמצא\u0004 כי בכל המקומות יחד כרת עימם \u0003ארבעים ושמונה בריתות\u0004 (שלוש פעמים שש עשרה) \u0003על כל מצוה ומצוה.\u0004","\u0003ר' שמעון מוציא\u0004 ממנין זה את \u0003הר גריזים והר עיבל,\u0004 שלא נאמרו שם אלא חלק מן המצוות, \u0003ומכניס אהל מועד שבמדבר. \u0004","\u0003ו\u0004מעירים שחולקים הם \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם של תנאים אלה]\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: כללות\u0004 (צוויים כלליים) \u0003נאמרו בסיני ופרטות\u0004 (פרטי המצוות) \u0003באהל מועד. ר' עקיבא אומר: כללות ופרטות נאמרו בסיני, ונשנו באהל מועד, ונשתלשו\u0004 (נאמרו פעם שלישית) \u0003בערבות מואב.\u0004 ור' שמעון סבור כר' עקיבא רבו, שיש למנות את הר סיני ואהל מועד כשני מקומות שבהם ניתנו כל המצוות.","\u0003ואין לך כל דבר מצוה ומצוה שכתובה בתורה שלא נכרתו עליה ארבעים ושמנה בריתות.\u0004","\u0003ר' שמעון בן יהודה איש כפר עכו אמר משום\u0004 (בשם) \u0003ר' שמעון: אין לך מצוה ומצוה שכתובה בתורה שלא נכרתו עליה ארבעים ושמנה בריתות של שש מאות אלף ושלשת אלפים וחמש מאות וחמשים\u0004 (כמניינם של בני ישראל במדבר), שכל אחד מישראל קיבל על עצמו את דברי הברית לעצמו וכערב לכל ישראל.","\u0003אמר רבי: לדברי ר' שמעון בן יהודה איש כפר עכו שאמר משום\u0004 (בשם) \u0003ר' שמעון, אין לך כל מצוה ומצוה שבתורה שלא נכרתו עליה ארבעים ושמנה בריתות של שש מאות אלף ושלשת אלפים וחמש מאות וחמשים. נמצא לכל אחד ואחד מישראל שש מאות אלף ושלשת אלפים וחמש מאות וחמשים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין דברי ר' שמעון איש כפר עכו ודברי רבי? שנראה שבא רבי להוסיף דברים ואין התוספת בדבריו ברורה. \u0003אמר רב משרשיא: ערבא וערבא דערבא\u0004 \u0005[ערב וערב לערב]\u0006 של חבירו \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת רבי כל אחד לא רק ערב לחבירו אלא אף ערב לשמירת אותה ערבות שחלה על חבירו, ונמצא מספר הבריתות מוכפל במספר כל ישראל פעם נוספת.","\u0003א\u0004 \u0003דרש ר' יהודה בן נחמני מתורגמניה\u0004 \u0005[מתורגמנו]\u0006 של \u0003ר' שמעון בן לקיש: כל הפרשה כולה\u0004 של ברכות וקללות \u0003לא נאמרה אלא בנואף ונואפת,\u0004 שהרי נאמר שם","\u0003\"ארור האיש אשר יעשה פסל ומסכה\" וגו'\u0004 (דברים כז, טו), וכי \u0003ב\"ארור\"\u0004 בלבד \u0003סגי ליה\u0004 \u0005[די לו]?\u0006 והרי הוא כופר בעיקר! \u0003אלא: זה הבא על הערוה והוליד\u0004 ממנה \u0003בן\u0004 ממזר, \u0003והלך\u0004 הבן שלא יכול היה לבוא בקהל \u0003לבין אומות העולם ועבד עבודה זרה —\u0004 \u0003ארורין אביו ואמו של זה שכך גרמו לו.\u0004 וכך כל האמור בקללות מתייחס רק לעבירות הנובעות מתוך הניאוף.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"ונתתה את הברכה על הר גרזים ואת הקללה\u0004 על הר עיבל\u0003\"\u0004 (דברים יא, כט), \u0003מה תלמוד לומר? אם ללמד שתהא ברכה על הר גריזים וקללה על הר עיבל —\u0004 \u0003הרי כבר נאמר \"אלה יעמדו לברך את העם על הר גרזים\"\u0004 (דברים כז, יב), \u0003וכתיב\u0004 \u0005ונאמר]\u0006 \u0003\"ואלה יעמדו על הקללה בהר עיבל\"\u0004 (דברים כז, יג)! \u0003אלא להקדים\u0004 אמירת ה\u0003ברכה ל\u0004אמירת ה\u0003קללה.\u0004","\u0003יכול יהיו כל הברכות קודמות לקללות —\u0004 \u0003תלמוד לומר: \"ברכה\" ו\"קללה\"\u0004 בלשון יחיד — \u0003ברכה אחת קודמת לקללה, ואין כל הברכות קודמות לקללות,\u0004 אלא לפי הסדר; ברכה וקללה, ברכה וקללה.","\u0003ולהקיש ברכה לקללה, לומר לך: מה קללה\u0004 נאמרה \u0003בלוים —\u0004 \u0003אף ברכה בלוים, ומה קללה בקול רם —\u0004 \u0003אף ברכה בקול רם, ומה קללה בלשון הקודש —\u0004 \u0003אף ברכה בלשון הקודש. ומה קללה בכלל ופרט —\u0004 \u0003אף ברכה בכלל ופרט, ומה קללה אלו ואלו\u0004 על שני ההרים \u0003עונין ואומרים \"אמן\" —\u0004 \u0003אף ברכה אלו ואלו עונין ואומרים \"אמן\".\u0004","\u0003ברכת כהנים כיצד\u0004 היתה נעשית? — \u0003במדינה\u0004 (מחוץ למקדש) \u0003אומר אותה שלש ברכות,\u0004 שמפסיקים בין פסוק לפסוק והקהל עונה \"אמן\" ביניהם, \u0003ובמקדש\u0004 אומר אותה כ\u0003ברכה אחת\u0004 והעם עונה אחר כולן \"ברוך ה' אלקים אלקי ישראל מן העולם ועד העולם\", כדרך שאומרים במקדש. \u0003במקדש אומר את השם\u0004"]]};
